INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cuál de los siguientes identificadores NO corresponde a un tipo de dato primitivo en Java?', 'String', 'boolean', 'double', 'char', 'A', 'Junior', 'String es una clase de objeto inmutable ubicada en el paquete java.lang, mientras que double, boolean y char son tipos primitivos.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué valor inicial por defecto asigna la JVM a un atributo booleano de instancia no inicializado?', 'null', 'false', 'true', '0', 'B', 'Junior', 'Los atributos primitivos de tipo boolean en las clases se inicializan automáticamente con false por la especificación de Java.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué palabra reservada se utiliza en Java para implementar la herencia entre dos clases?', 'implements', 'inherits', 'extends', 'super', 'C', 'Junior', 'La palabra reservada extends establece herencia de clases, mientras que implements se utiliza exclusivamente para interfaces.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cuál es la firma exacta del método principal requerida para iniciar la ejecución de una aplicación estándar en Java?', 'protected static void start(String[] args)', 'public void main(String[] args)', 'public static int main(String args[])', 'public static void main(String[] args)', 'D', 'Junior', 'La JVM requiere obligatoriamente public static void main(String[] args) como punto de entrada ejecutable.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué diferencia existe entre el operador == y equals() al comparar objetos?', '== compara referencias de memoria y equals() compara contenido o estado.', '== compara valores primitivos y equals() solo compara cadenas String.', 'equals() es más rápido porque omite la validación de tipos.', 'No existe ninguna diferencia funcional entre ambos en Java.', 'A', 'Junior', '== valida si apuntan al mismo objeto en memoria; equals() compara equivalencia.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué estructura de control de excepciones se ejecuta siempre, independientemente de si ocurrió un error o no?', 'catch', 'finally', 'throw', 'throws', 'B', 'Junior', 'El bloque finally se ejecuta de manera garantizada para tareas de limpieza como cerrar flujos o conexiones.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué anotación principal de Spring Boot habilita la autoconfiguración, el escaneo de componentes y la configuración de propiedades?', '@EnableAutoConfiguration', '@ComponentScan', '@SpringBootApplication', '@Configuration', 'C', 'Junior', '@SpringBootApplication es una anotación compuesta que agrupa @Configuration, @EnableAutoConfiguration y @ComponentScan.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué anotación de Spring se utiliza para inyectar automáticamente dependencias gestionadas por el contenedor de inversión de control?', '@ResourceBean', '@Injectable', '@ComponentBind', '@Autowired', 'D', 'Junior', '@Autowired le indica al contenedor de Spring que resuelva e inyecte el bean colaborador requerido en el campo, setter o constructor.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cuál de las siguientes interfaces pertenece al framework de colecciones y NO permite elementos duplicados?', 'Set', 'Queue', 'List', 'Vector', 'A', 'Junior', 'La interfaz java.util.Set modela el concepto matemático de conjunto y no admite elementos duplicados.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué anotación de Spring MVC se coloca a nivel de clase para crear controladores REST donde las respuestas se serializan automáticamente a JSON?', '@Controller', '@RestController', '@WebEndpoint', '@JsonController', 'B', 'Junior', '@RestController combina @Controller y @ResponseBody, haciendo que los retornos de los métodos se serialicen directamente en el cuerpo HTTP.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cuál es el modificador de acceso más restrictivo en Java?', 'protected', 'package-private (default)', 'private', 'public', 'C', 'Junior', 'El modificador private restringe la visibilidad del miembro únicamente al interior de la propia clase que lo define.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué anotación de Spring se utiliza comúnmente para marcar la capa de acceso a datos y permitir la traducción de excepciones de persistencia?', '@Service', '@DatabaseClient', '@Dao', '@Repository', 'D', 'Junior', '@Repository marca los componentes de acceso a datos y habilita la conversión automática de excepciones de persistencia a DataAccessException.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Por qué se desaconseja concatenar String con el operador + dentro de bucles?', 'Crea múltiples objetos intermedios en memoria degradando el rendimiento.', 'Provoca un error de compilación en versiones modernas de Java.', 'Sobrescribe el valor de las variables locales en el stack.', 'Impide la ejecución del recolector de basura en el heap.', 'A', 'Junior', 'Cada concatenación genera un nuevo String; se recomienda usar StringBuilder.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué anotación de Spring se coloca sobre la capa que contiene la lógica de negocio de la aplicación?', '@Component', '@Service', '@Logic', '@BusinessModule', 'B', 'Junior', '@Service es una especialización semántica de @Component diseñada específicamente para encapsular la lógica de negocio.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué método de la clase Object debe ser sobreescrito junto con equals() para mantener la coherencia en colecciones basadas en hash?', 'toString()', 'clone()', 'hashCode()', 'finalize()', 'C', 'Junior', 'El contrato general de Java establece que si dos objetos son iguales según equals(), deben devolver obligatoriamente el mismo hashCode().', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué palabra reservada impide que una clase sea extendida o que un método sea sobreescrito en Java?', 'static', 'abstract', 'const', 'final', 'D', 'Junior', 'Aplicar final a una clase evita que sea heredada, y aplicado a un método impide que clases hijas lo sobreescriban.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué archivo de configuración estándar en formato clave-valor utiliza Spring Boot para configurar puertos y base de datos?', 'application.properties', 'pom.xml', 'beans.xml', 'server.config', 'A', 'Junior', 'application.properties (o application.yml) es el archivo estándar de propiedades de configuración que Spring Boot lee automáticamente.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué interfaz funcional de java.util.function recibe un argumento y no retorna ningún resultado?', 'Function<T, R>', 'Consumer<T>', 'Predicate<T>', 'Supplier<T>', 'B', 'Junior', 'Consumer<T> define el método accept(T t), el cual consume el valor entregado y tiene retorno void.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué tipo de excepción en Java deriva de RuntimeException y no requiere ser declarada obligatoriamente en la cláusula throws?', 'Checked Exception', 'Error de compilación', 'Unchecked Exception', 'Fatal Exception', 'C', 'Junior', 'Las subclases de RuntimeException y Error son excepciones no verificadas (unchecked) que el compilador no exige atrapar o declarar.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué interfaz básica de Spring Data permite operaciones CRUD básicas sin necesidad de escribir consultas SQL manualmente?', 'EntityHandler', 'SqlTemplate', 'JdbcDaoSupport', 'CrudRepository', 'D', 'Junior', 'CrudRepository proporciona métodos genéricos como save(), findById(), findAll() y deleteById() listos para su uso.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué estructura de datos almacena pares clave-valor en Java garantizando tiempo constante promedio O(1) en búsquedas?', 'HashMap', 'LinkedList', 'TreeMap', 'TreeSet', 'A', 'Junior', 'HashMap utiliza tablas hash con hashing de claves, ofreciendo complejidad O(1) en promedio para inserción y recuperación.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué anotación de Spring se utiliza para extraer variables de la ruta en una URL REST (ejemplo: /usuarios/{id})?', '@RequestParam', '@PathVariable', '@RequestHeader', '@RequestBody', 'B', 'Junior', '@PathVariable enlaza un segmento dinámico definido en la plantilla URI directamente a un parámetro del método del controlador.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cuál es el propósito de la palabra reservada super en el constructor de una subclase en Java?', 'Otorgar permisos administrativos al hilo de ejecución para omitir chequeos de seguridad.', 'Crear una segunda instancia aislada de la clase padre en un espacio de memoria independiente.', 'Invocar el constructor de la superclase para inicializar adecuadamente el estado heredado.', 'Indicar al recolector de basura que la instancia actual no debe ser destruida al salir del ámbito.', 'C', 'Junior', 'super(...) invoca el constructor de la clase padre directa y debe ser obligatoriamente la primera sentencia del constructor hijo.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué herramienta de construcción y gestión de dependencias en Java utiliza el archivo pom.xml?', 'Gradle', 'Ant', 'Make', 'Maven', 'D', 'Junior', 'Apache Maven utiliza el archivo Project Object Model (pom.xml) para la definición de dependencias, plugins y ciclo de construcción.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué interfaz funcional recibe un objeto de entrada y retorna un valor booleano verdadero o falso?', 'Predicate<T>', 'Supplier<T>', 'Consumer<T>', 'UnaryOperator<T>', 'A', 'Junior', 'Predicate<T> define el método test(T t) y se utiliza con frecuencia en operaciones de filtrado en Streams.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué anotación de Spring se coloca sobre un método en una clase @Configuration para que su valor retornado sea registrado como Bean?', '@Component', '@Bean', '@Service', '@Inject', 'B', 'Junior', '@Bean se coloca sobre métodos dentro de clases @Configuration para registrar manualmente una instancia en el ApplicationContext.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué método de la interfaz java.lang.Runnable se debe implementar para definir la tarea que ejecutará un hilo?', 'start()', 'execute()', 'run()', 'init()', 'C', 'Junior', 'Runnable define el método abstracto public void run(), el cual contiene el código que ejecutará el hilo de ejecución.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué anotación de Spring se emplea para extraer los parámetros de consulta (query params) de una URL como ?pagina=2?', '@QueryString', '@PathVariable', '@MatrixVariable', '@RequestParam', 'D', 'Junior', '@RequestParam asocia los query parameters o parámetros de formulario multipart/urlencoded a variables en el controlador.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cuál de las siguientes afirmaciones describe con precisión a una clase abstracta en Java?', 'No puede ser instanciada directamente mediante el operador new y sirve como plantilla base.', 'No puede contener atributos ni métodos concretos con cuerpo implementado en su código.', 'Puede heredar simultáneamente de múltiples clases abstractas mediante herencia múltiple.', 'Todos sus métodos deben ser obligatoriamente declarados con el modificador public static.', 'A', 'Junior', 'Las clases abstractas definen contratos y comportamientos compartidos, pero no pueden instanciarse directamente.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué alcance (scope) tienen los Beans de Spring por defecto si no se especifica ninguna anotación @Scope adicional?', 'prototype', 'singleton', 'request', 'session', 'B', 'Junior', 'El alcance predeterminado de Spring es singleton, lo que significa que existe una única instancia compartida por contenedor IoC.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué sentencia permite liberar recursos de manera automática al finalizar un bloque try sin requerir un bloque finally explícito?', 'try-catch-finally tradicional', 'synchronized block con monitor', 'try-with-resources con AutoCloseable', 'assert statement con validación', 'C', 'Junior', 'try-with-resources cierra automáticamente cualquier objeto que implemente java.lang.AutoCloseable al salir del bloque.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué anotación de Spring se utiliza para mapear peticiones HTTP de tipo POST a un método controlador específico?', '@GetMapping', '@PutMapping', '@ActionMapping', '@PostMapping', 'D', 'Junior', '@PostMapping es un atajo especializado para @RequestMapping(method = RequestMethod.POST).', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cuál es la función del recolector de basura (Garbage Collector) en la máquina virtual de Java?', 'Liberar automáticamente la memoria del Heap ocupada por objetos que ya no son alcanzables.', 'Compilar el código fuente a bytecode optimizado antes de ejecutar la aplicación.', 'Verificar las firmas criptográficas de los archivos .jar para evitar inyecciones maliciosas.', 'Controlar el acceso a los registros del procesador y sincronizar la caché L1 de hardware.', 'A', 'Junior', 'El Garbage Collector rastrea referencias en el Heap y reclama la memoria de objetos que ya no tienen referencias activas.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué anotación en Spring se coloca sobre un parámetro de método para deserializar el cuerpo JSON de la petición HTTP a un objeto Java?', '@ResponseBody', '@RequestBody', '@ModelAttribute', '@RequestPart', 'B', 'Junior', '@RequestBody le indica a Spring que lea el cuerpo HTTP entrante y utilice HttpMessageConverter (como Jackson) para convertirlo a objeto.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué garantiza declarar una variable compartida como volatile en Java?', 'Garantiza atomicidad completa en operaciones de incremento.', 'Bloquea el hilo actual durante la lectura de la variable.', 'Garantiza visibilidad directa de cambios entre hilos en memoria.', 'Almacena la variable permanentemente en el pool de constantes.', 'C', 'Semi-Senior', 'volatile asegura que las lecturas y escrituras vayan a memoria principal.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué anotación declarativa de Spring administra transacciones automáticamente abriendo, confirmando o revirtiendo la sesión?', '@AtomicOperation', '@RollbackOnFail', '@TransactionManaged', '@Transactional', 'D', 'Semi-Senior', '@Transactional delega en el TransactionManager de Spring la apertura, commit o rollback ante RuntimeExceptions.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Por qué se prefiere la inyección por constructor sobre la inyección por campo?', 'Facilita la inmutabilidad, el testing unitario y evita dependencias nulas.', 'Incrementa la velocidad de compilación de los controladores web.', 'Elimina la necesidad de definir anotaciones en clases de configuración.', 'Permite crear beans sin necesidad de instanciar la clase en el heap.', 'A', 'Semi-Senior', 'La inyección por constructor promueve beans inmutables y tests sin reflection.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', 'En el API de Streams de Java, ¿cuál de las siguientes operaciones es una operación TERMINAL que produce un resultado y cierra el stream?', 'filter()', 'collect()', 'map()', 'distinct()', 'B', 'Semi-Senior', 'collect() es una operación terminal que procesa los elementos del flujo y los empaqueta en una colección final, dando fin al Stream.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué nivel de propagación transaccional en Spring ejecuta el método en una transacción física independiente y suspende la transacción actual si existía?', 'Propagation.REQUIRED', 'Propagation.NESTED', 'Propagation.REQUIRES_NEW', 'Propagation.SUPPORTS', 'C', 'Semi-Senior', 'REQUIRES_NEW siempre suspende cualquier transacción externa preexistente e inicia una transacción física independiente y aislada.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cómo gestiona la concurrencia interna la clase ConcurrentHashMap en comparación con Hashtable?', 'Bloquea el mapa completo en cada lectura y escritura mediante un monitor global sincronizado.', 'Delega la persistencia en archivos temporales del sistema operativo para evitar colisiones.', 'Copia la tabla completa en cada operación de escritura similar a CopyOnWriteArrayList.', 'Permite lecturas sin bloqueo y utiliza bloqueos segmentados o CAS a nivel de cubeta individual (bucket).', 'D', 'Semi-Senior', 'ConcurrentHashMap permite lecturas concurrentes sin cerrojo y limita los bloqueos a la cubeta específica que se modifica con CAS y locks finos.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué anotación de Spring Data JPA permite escribir consultas personalizadas en sintaxis JPQL o SQL nativo?', '@Query', '@SelectQuery', '@JpaMapping', '@NativeSql', 'A', 'Semi-Senior', '@Query se coloca sobre métodos de interfaces de repositorio para definir consultas JPQL o consultas SQL nativas con nativeQuery = true.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué método del ciclo de vida de un Bean de Spring se ejecuta inmediatamente después de que el contenedor ha inyectado todas las dependencias?', '@PreDestroy', '@PostConstruct', '@BeanInit', '@OnLoaded', 'B', 'Semi-Senior', 'La anotación @PostConstruct de javax.annotation / jakarta.annotation marca el método de inicialización que corre tras la inyección de dependencias.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cuál es la diferencia principal entre map() y flatMap() en Java Streams?', 'map() es una operación terminal y flatMap() es intermedia.', 'flatMap() filtra elementos mientras que map() los ordena de forma natural.', 'map() transforma elementos 1 a 1 y flatMap() aplana streams anidados.', 'flatMap() solo funciona sobre colecciones inmutables de tipo Set.', 'C', 'Semi-Senior', 'flatMap transforma cada elemento en un stream y luego aplana los resultados.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué módulo de Spring Boot proporciona endpoints listos para producción para monitorear métricas, salud (health) e información de la aplicación?', 'Spring Boot DevTools', 'Spring Boot Inspector', 'Spring Boot Admin', 'Spring Boot Actuator', 'D', 'Semi-Senior', 'Spring Boot Actuator expone endpoints como /actuator/health, /actuator/metrics y /actuator/info para monitoreo operativo.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cuál es el propósito principal de Optional<T> como retorno en Java?', 'Expresar explícitamente la posible ausencia de un valor y evitar NPE.', 'Reemplazar el uso de colecciones vacías como listas y conjuntos.', 'Serializar objetos de forma binaria en sistemas distribuidos.', 'Optimizar el uso de memoria RAM reduciendo el tamaño del objeto.', 'A', 'Semi-Senior', 'Optional comunica a quien invoca que el resultado puede no estar presente.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué anotación se utiliza en Spring para capturar excepciones globales y centralizar el manejo de errores en toda la aplicación REST?', '@ErrorHandler', '@ControllerAdvice (o @RestControllerAdvice)', '@GlobalCatch', '@ExceptionFilter', 'B', 'Semi-Senior', '@RestControllerAdvice combina @ControllerAdvice con @ResponseBody para manejar excepciones transversalmente con métodos @ExceptionHandler.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué estructura de hilos de java.util.concurrent se debe utilizar para ejecutar tareas concurrentes reutilizando un grupo fijo de hilos?', 'ThreadFactory', 'ForkJoinTask', 'Executors.newFixedThreadPool(n)', 'CompletableFuturePool', 'C', 'Semi-Senior', 'newFixedThreadPool crea un ExecutorService con un número constante de hilos reutilizables y una cola de tareas compartida.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué anotación de Spring permite inyectar valores desde archivos de propiedades o variables de entorno mediante expresiones SpEL como \"${app.servidor.url}\"?', '@PropertySource', '@ConfigurationProperties', '@InjectValue', '@Value', 'D', 'Semi-Senior', '@Value(\"${propiedad}\") inyecta valores de configuración directamente en variables de instancia en tiempo de construcción del Bean.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cómo utiliza Spring los Proxies dinámicos en clases con anotaciones como @Transactional?', 'Intercepta llamadas a métodos para aplicar lógica transversal como transacciones.', 'Compila el código Java directamente a lenguaje ensamblador de la máquina.', 'Sustituye la máquina virtual por un contenedor nativo en memoria.', 'Desactiva el recolector de basura durante la ejecución del método.', 'A', 'Semi-Senior', 'Los proxies interceptan la invocación para iniciar y confirmar transacciones.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué estrategia de @GeneratedValue delega el ID a una columna AUTO_INCREMENT de MySQL?', 'GenerationType.SEQUENCE', 'GenerationType.IDENTITY', 'GenerationType.AUTO', 'GenerationType.TABLE', 'B', 'Semi-Senior', 'IDENTITY utiliza columnas autonuméricas nativas del motor relacional.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué excepción lanza un Iterator fail-fast si se modifica la colección concurrentemente?', 'IllegalStateException', 'UnsupportedOperationException', 'ConcurrentModificationException', 'IndexOutOfBoundsException', 'C', 'Semi-Senior', 'Los iteradores fail-fast detectan cambios estructurales y lanzan la excepción.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué anotación de Spring habilita el almacenamiento en caché de resultados de métodos para evitar consultas repetitivas a la base de datos?', '@CacheMemo', '@StoreResult', '@Remember', '@Cacheable', 'D', 'Semi-Senior', '@Cacheable indica a Spring que almacene en el caché configurado el resultado del método asociado a los argumentos provistos.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cuál es la diferencia entre CompletableFuture y el antiguo Future<T> introducido en Java 5?', 'CompletableFuture permite componer cadenas asíncronas no bloqueantes con callbacks como thenApply() y manejar excepciones funcionalmente.', 'Future permite ejecutar múltiples hilos simultáneos, mientras que CompletableFuture se ejecuta en un solo hilo síncrono.', 'CompletableFuture solo funciona con sistemas de archivos y no admite conexiones de red concurrentes.', 'No existen diferencias en la API excepto el soporte para serialización en formatos XML.', 'A', 'Semi-Senior', 'CompletableFuture introduce composición funcional asíncrona, combinación de futuros y callbacks sin requerir llamadas bloqueantes a get().', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué interfaz de Spring Security se implementa típicamente para cargar los datos del usuario desde la base de datos durante la autenticación?', 'AuthenticationManager', 'UserDetailsService', 'SecurityFilterChain', 'PasswordEncoder', 'B', 'Semi-Senior', 'UserDetailsService define el método loadUserByUsername(String username) para retornar la entidad UserDetails necesaria para autenticar.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué mecanismo de carga utiliza la anotación @OneToMany de JPA por defecto según la especificación?', 'FetchType.EAGER (carga inmediata)', 'FetchType.PARALLEL (carga asíncrona en hilo secundario)', 'FetchType.LAZY (carga perezosa bajo demanda)', 'FetchType.BATCH (carga agrupada en bloques fijos)', 'C', 'Semi-Senior', 'Por especificación JPA, las relaciones a colección (@OneToMany y @ManyToMany) usan por defecto FetchType.LAZY para evitar sobrecarga.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué clase de Java 8 se debe preferir para manejar fechas y horas con huso horario de forma inmutable?', 'java.util.Date', 'java.util.Calendar', 'java.sql.Timestamp', 'java.time.ZonedDateTime', 'D', 'Semi-Senior', 'ZonedDateTime en java.time es inmutable, thread-safe y almacena fecha, hora y reglas de zona horaria (ZoneId).', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué anotación de Spring se utiliza para condicionar la creación de un Bean solo si una propiedad específica está presente y activa?', '@ConditionalOnProperty', '@RequiresProperty', '@IfConfigured', '@PropertyMatch', 'A', 'Semi-Senior', '@ConditionalOnProperty permite registrar beans condicionalmente en función del valor o presencia de una propiedad en el entorno.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cómo resuelve Java el conflicto si dos interfaces definen el mismo método default?', 'Ejecuta aleatoriamente la implementación de cualquiera de las interfaces.', 'Obliga a la clase implementadora a sobrescribir el método en conflicto.', 'Ignora ambos métodos y genera un error silencioso en tiempo de ejecución.', 'Hereda siempre el método de la interfaz declarada en primer lugar.', 'B', 'Semi-Senior', 'El compilador exige desambiguar implementando explícitamente el método.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué anotación de Spring Data JPA se coloca sobre un método del repositorio para indicar que ejecuta una consulta UPDATE o DELETE?', '@QueryChange', '@TransactionalWrite', '@Modifying', '@UpdateOperation', 'C', 'Semi-Senior', '@Modifying le indica a Spring Data JPA que la consulta ejecutada altera el estado de la base de datos (DML) y no es un simple SELECT.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué patrón estructural utiliza la clase java.lang.StringBuilder para encadenar llamadas como .append(\"a\").append(\"b\")?', 'Factory Pattern', 'Singleton Pattern', 'Observer Pattern', 'Builder / Fluent Interface Pattern', 'D', 'Semi-Senior', 'StringBuilder retorna this en cada llamada de método append(), implementando una interfaz fluida del patrón Builder.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué componente central de Spring Web MVC intercepta todas las peticiones HTTP entrantes y las despacha a los controladores registrados?', 'DispatcherServlet', 'ContextLoaderListener', 'FilterSecurityInterceptor', 'HandlerMappingEngine', 'A', 'Semi-Senior', 'DispatcherServlet actúa como Front Controller en la arquitectura de Spring Web MVC, coordinando handlers, controladores y vistas.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué retorna el método add() de un Set cuando se intenta agregar un elemento repetido?', 'Lanza un DuplicateKeyException al detectar la colisión.', 'Retorna false y el conjunto permanece sin modificaciones.', 'Retorna true y sobrescribe el elemento ya existente.', 'Elimina todos los elementos previos del conjunto.', 'B', 'Semi-Senior', 'Set.add() retorna false si el elemento ya existe según equals() y hashCode().', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué anotación de Spring Boot permite vincular de forma tipada un prefijo completo de propiedades YAML o properties a una clase Java?', '@EnvBinding', '@PropertyMapping', '@ConfigurationProperties', '@ValueHolder', 'C', 'Semi-Senior', '@ConfigurationProperties(prefix = \"app\") enlaza jerárquicamente grupos de propiedades de configuración a campos de un bean con validación.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cuál es la función del método intern() en la clase String de Java?', 'Generar una copia encriptada de la cadena para almacenamiento en variables locales.', 'Traducir el contenido de la cadena a caracteres internacionales UTF-16 en tiempo de ejecución.', 'Limpiar los espacios en blanco iniciales y finales de la cadena de forma destructiva.', 'Colocar o recuperar la instancia de cadena dentro del String Constant Pool de la JVM para compartir memoria.', 'D', 'Semi-Senior', 'intern() garantiza que todas las cadenas con el mismo contenido textual compartan la misma referencia en el String Pool.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué sucede cuando se anota un método con @Async en Spring?', 'El método se ejecuta de forma asíncrona en un hilo separado gestionado por un TaskExecutor sin bloquear al invocador.', 'La base de datos ejecuta la consulta en modo no bloqueante mediante WebClient exclusivamente.', 'La máquina virtual detiene los procesos en segundo plano para dedicar el 100% de la CPU al método.', 'El método se convierte obligatoriamente en una función recursiva con control de pila.', 'A', 'Semi-Senior', '@Async delega la ejecución del método a un TaskExecutor en un hilo independiente, requiriendo tener activa @EnableAsync.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cuál es la forma idónea de manejar checked exceptions dentro de un map() en Streams?', 'Usar throws directamente en la expresión lambda del stream.', 'Envolver la lógica en un try-catch o una función envolvente de tipo wrapper.', 'Desactivar el chequeo de excepciones con la directiva @IgnoreException.', 'Castear el Stream a un objeto de tipo ParallelStream.', 'B', 'Semi-Senior', 'Las lambdas funcionales de Streams no admiten checked exceptions sin manejo.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué anotación de Spring se emplea para resolver ambigüedad cuando existen dos o más Beans del mismo tipo candidatos para inyección?', '@SpecificBean', '@Discriminator', '@Qualifier', '@UniqueCandidate', 'C', 'Semi-Senior', '@Qualifier(\"nombreBean\") especifica exactamente qué bean debe ser inyectado cuando existen múltiples alternativas del mismo tipo.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cómo divide la memoria del Heap el recolector de basura G1 de la JVM?', 'En dos únicas áreas monolíticas contiguas de tamaño fijo e inalterable.', 'En pilas dinámicas asignadas exclusivamente a cada hilo del sistema.', 'En una única región continua sin división generacional.', 'En múltiples regiones independientes de igual tamaño asignadas por roles.', 'D', 'Senior', 'G1 divide el heap en regiones iguales (1MB a 32MB) que actúan como Eden/Old.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Por qué @Transactional falla al invocarse desde otro método de la misma clase?', 'La llamada interna a this omite el proxy transaccional de Spring.', 'Spring bloquea las transacciones recursivas por motivos de seguridad.', 'La conexión a la base de datos se cierra automáticamente al primer paso.', 'Los métodos públicos de la misma clase comparten el mismo hilo JDBC.', 'A', 'Senior', 'Al invocar internamente a this, la llamada no pasa por el proxy interceptor.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué solución resuelve eficazmente el problema de N+1 queries en JPA?', 'Cambiar la estrategia de carga de relaciones de EAGER a LAZY.', 'Utilizar JOIN FETCH en consultas JPQL o definir Entity Graphs.', 'Desactivar el contexto de persistencia en cada consulta SELECT.', 'Configurar la base de datos con aislamiento TRANSACTION_NONE.', 'B', 'Senior', 'JOIN FETCH carga la entidad y sus asociaciones en una única consulta SQL.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué asegura la regla Happens-Before en el modelo de memoria de Java (JMM)?', 'Que los hilos finalicen su ejecución en el orden en que fueron creados.', 'Que la memoria no sufra nunca errores de desbordamiento OutOfMemoryError.', 'Que la escritura de un hilo sea visible de forma predecible por otro hilo.', 'Que la recolección de basura ocurra antes de instanciar nuevos objetos.', 'C', 'Senior', 'Happens-before garantiza coherencia y visibilidad entre operaciones multihilo.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cuál es el rol de SecurityFilterChain en Spring Security 6?', 'Conectarse directamente al servidor LDAP para validar usuarios.', 'Generar tablas de roles y permisos automáticamente en la base.', 'Compilar reglas de seguridad a nivel de bytecode en el arranque.', 'Definir y ordenar la cadena de filtros de autenticación y autorización.', 'D', 'Senior', 'SecurityFilterChain especifica los filtros HTTP aplicados a cada endpoint.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué optimización permite el Escape Analysis en el compilador JIT de Java?', 'Asignar objetos en el Stack en lugar del Heap y eliminar sincronizaciones.', 'Comprimir el código fuente para reducir el tamaño del archivo JAR.', 'Cerrar sockets de red que no se utilicen tras un periodo de inactividad.', 'Descargar clases no utilizadas para liberar el Metaspace de la JVM.', 'A', 'Senior', 'Si un objeto no escapa del método, se puede scalarizar o ubicar en el stack.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué excepción lanza JPA cuando falla un bloqueo optimista con @Version?', 'ConcurrentUpdateException', 'OptimisticLockException', 'StaleDataSQLException', 'TransactionRolledBackException', 'B', 'Senior', 'Se lanza OptimisticLockException si la versión en DB difiere de la cargada.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cuál es la principal ventaja de los Virtual Threads en Java 21?', 'Multiplican la velocidad de cálculo intensivo de la CPU por diez.', 'Reemplazan el recolector de basura tradicional por uno en tiempo real.', 'Permiten millones de hilos ligeros bloqueantes en I/O con mínimo consumo.', 'Eliminan la necesidad de sincronizar variables compartidas entre hilos.', 'C', 'Senior', 'Los hilos virtuales se montan en carrier threads al bloquearse por I/O.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Por qué una colección estática no limpiada provoca fuga de memoria en Java?', 'Porque el compilador javac prohíbe liberar memoria estática.', 'Porque la JVM bloquea la recolección en variables final.', 'Porque las variables estáticas se almacenan en el registro del CPU.', 'Porque sus objetos permanecen alcanzables desde la raíz GC Root.', 'D', 'Senior', 'Los objetos referenciados por clases cargadas (GC roots) nunca son recolectados.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué estado adopta un Circuit Breaker cuando detecta una alta tasa de fallos?', 'OPEN: rechaza llamadas inmediatas sin consultar al servicio remoto.', 'CLOSED: duplica el ancho de banda para compensar la latencia.', 'HALF-OPEN: apaga el contenedor de Spring Boot para reiniciarlo.', 'LOCKED: bloquea el hilo principal hasta recibir una respuesta HTTP.', 'A', 'Senior', 'El estado OPEN corta el flujo para dar tiempo de recuperación al servicio.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cuál es el objetivo principal del recolector ZGC en la JVM de Java?', 'Minimizar el uso de memoria RAM a expensas de pausas prolongadas.', 'Garantizar tiempos de pausa sub-milisegundos en heaps de hasta 16TB.', 'Desactivar la compilación JIT para mejorar el arranque en frío.', 'Evitar la fragmentación ejecutando la recolección de noche.', 'B', 'Senior', 'ZGC realiza casi todo el trabajo de forma concurrente con pausas < 1 ms.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cuál es la mejor práctica de arquitectura para resolver dependencias circulares?', 'Habilitar spring.main.allow-circular-references=true en producción.', 'Usar anotaciones @Lazy en todos los atributos de cada componente.', 'Refactorizar extrayendo la responsabilidad común a un tercer servicio.', 'Convertir los beans en clases abstractas con métodos estáticos.', 'C', 'Senior', 'Extraer un servicio mediador o usar eventos elimina el acoplamiento cíclico.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué controla el parámetro -XX:MaxDirectMemorySize en la JVM?', 'El tamaño máximo de memoria asignado a la pila de cada hilo.', 'La memoria reservada para el almacenamiento de código del JIT.', 'El espacio máximo del área Metaspace para metadatos de clases.', 'El límite de memoria fuera del Heap asignada vía NIO DirectByteBuffer.', 'D', 'Senior', 'Limita la memoria off-heap que librerías como Netty usan para buffers directos.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cuál es la función principal de la anotación @CacheEvict en Spring Framework?', 'Eliminar una o múltiples entradas obsoletas de la memoria caché cuando se realizan operaciones de actualización o eliminación.', 'Deshabilitar de forma permanente el uso de caché en todos los controladores de la aplicación web.', 'Comprimir los datos del caché utilizando algoritmos gzip para reducir el consumo de memoria en disco.', 'Forzar la recarga síncrona de toda la base de datos en el arranque de la aplicación.', 'A', 'Senior', '@CacheEvict limpia entradas específicas o todo el caché (allEntries = true) para asegurar consistencia ante escrituras.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué anomalía de concurrencia previene el nivel de aislamiento SERIALIZABLE?', 'Solo lecturas sucias (Dirty Reads).', 'Lecturas fantasma, lecturas no repetibles y lecturas sucias.', 'Exclusivamente la pérdida de actualizaciones concurrentes.', 'Ninguna, solo optimiza la velocidad de las consultas SELECT.', 'B', 'Senior', 'SERIALIZABLE es el nivel más estricto y previene lecturas fantasma (Phantom).', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué principio rige la delegación de carga en los ClassLoaders clásicos de Java?', 'Primero en entrar, primero en salir (FIFO) en memoria.', 'Carga directa en memoria sin consultar a ninguna clase previa.', 'Delegación hacia el ClassLoader padre antes de intentar cargar.', 'Inversión de dependencias basada exclusivamente en anotaciones.', 'C', 'Senior', 'Un ClassLoader delega la búsqueda a su padre antes de buscar la clase él mismo.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué tipo de ataque mitiga la inclusión de tokens CSRF en aplicaciones web?', 'Inyección de código SQL malicioso en formularios de búsqueda.', 'Ataques de denegación de servicio distribuido (DDoS) masivo.', 'Robo de contraseñas mediante fuerza bruta en el endpoint de login.', 'Peticiones no autorizadas enviadas desde un sitio externo de confianza.', 'D', 'Senior', 'CSRF previene que un sitio malicioso ejecute acciones en nombre del usuario.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Por qué LongAdder ofrece mejor rendimiento que AtomicLong bajo alta contención?', 'Distribuye la cuenta en celdas internas reduciendo colisiones de CAS.', 'Evita el uso de memoria RAM delegando los conteos a la tarjeta gráfica.', 'Utiliza bloqueos sincronizados a nivel de kernel del sistema operativo.', 'Descarta operaciones duplicadas mediante compresión de datos en memoria.', 'A', 'Senior', 'LongAdder mantiene un arreglo de celdas que hilos concurrentes actualizan.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué servidor embebido utiliza por defecto Spring WebFlux para I/O no bloqueante?', 'Apache Tomcat con hilos síncronos clásicos.', 'Reactor Netty basado en bucles de eventos no bloqueantes.', 'GlassFish Application Server.', 'Red Hat WildFly Server.', 'B', 'Senior', 'WebFlux utiliza Reactor Netty con event-loops para alta concurrencia no bloqueante.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿En qué momento recolecta el GC los objetos apuntados por una SoftReference?', 'Inmediatamente en el siguiente ciclo de recolección menor.', 'Nunca son recolectados mientras la JVM permanezca encendida.', 'Solo cuando la JVM experimenta escasez crítica de memoria disponible.', 'Cuando el hilo que creó la referencia finaliza su ejecución.', 'C', 'Senior', 'SoftReference se conserva hasta que la memoria es escasa (ideal para cachés).', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué técnica se utiliza con Testcontainers en pruebas de integración para Spring Boot?', 'Empaquetar todos los tests en un archivo ZIP para enviarlos a un servidor remoto de análisis estático, mediante la delegación de responsabilidades a proxies dinámicos y componentes gestionados.', 'Simular completamente el kernel del sistema operativo dentro del código fuente de la prueba unitaria, permitiendo el procesamiento asíncrono no bloqueante con alto rendimiento computacional.', 'Compilar la aplicación a código nativo antes de ejecutar las aserciones de JUnit, garantizando la seguridad de tipos y la coherencia en la memoria compartida de la JVM.', 'Levantar instancias reales y desechables de bases de datos o servicios (PostgreSQL, Kafka, Redis) en contenedores Docker durante la ejecución del test.', 'D', 'Senior', 'Testcontainers permite ejecutar pruebas de integración fiables contra servicios reales empaquetados en contenedores Docker efímeros.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿En qué consiste el algoritmo Work-Stealing en el pool Fork/Join de Java?', 'Hilos desocupados roban tareas del final de la cola de hilos ocupados.', 'El hilo principal roba memoria de otros procesos del sistema operativo.', 'Las tareas pendientes se envían a un nodo externo en la nube.', 'Cancela las tareas más lentas para priorizar las más rápidas.', 'A', 'Senior', 'Work-stealing maximiza el uso de CPU permitiendo robar subtareas pendientes.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cuál es el beneficio de integrar Flyway o Liquibase en proyectos Spring Boot?', 'Generar controladores REST a partir de esquemas de bases de datos.', 'Versionar y aplicar migraciones de esquema de base de datos ordenadamente.', 'Reemplazar el uso de drivers JDBC por conexiones directas de red.', 'Monitorear el rendimiento de consultas lentas en tiempo real.', 'B', 'Senior', 'Garantiza migraciones reproducibles y versionadas entre distintos ambientes.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué optimización de compilación realiza el compilador JIT conocida como \"Method Inlining\"?', 'Mueve los métodos estáticos a un espacio de memoria fuera del proceso de la máquina virtual de Java.', 'Convierte todas las clases abstractas en interfaces para acelerar la resolución de enlaces dinámicos en tiempo de ejecución.', 'Reemplaza la llamada a un método pequeño por el cuerpo del código del método directamente en el sitio de invocación, eliminando sobrecostes de pila.', 'Elimina las comprobaciones de tipos de datos en tiempo de compilación para generar archivos ejecutables más pequeños.', 'C', 'Senior', 'Method Inlining elimina el overhead de frame de llamada en stack y habilita subsecuentes optimizaciones como dead code elimination y constant folding.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué ventaja ofrece usar ApplicationEventPublisher para la comunicación interna?', 'Reemplaza el uso de HTTP para comunicación externa con clientes.', 'Elimina la necesidad de utilizar bases de datos relacionales.', 'Obliga a que todos los métodos se ejecuten de forma asíncrona.', 'Desacopla componentes emisores de receptores mediante publicación de eventos.', 'D', 'Senior', 'Promueve bajo acoplamiento al emitir eventos sin conocer a los listeners.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Por qué se prefiere el patrón Saga sobre 2PC en arquitecturas de microservicios?', 'Evita bloqueos síncronos distribuidos mediante transacciones compensatorias.', 'Permite usar SQL en bases de datos NoSQL sin configuración adicional.', 'Garantiza consistencia estricta instantánea en toda la red.', 'Reduce el costo de almacenamiento en discos SSD del servidor.', 'A', 'Senior', 'Saga divide la transacción en pasos locales con acciones compensatorias si falla.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cómo funciona el mecanismo de Dirty Checking en Hibernate?', 'Escanea tablas en segundo plano para borrar registros obsoletos.', 'Compara el estado actual con la instantánea original para emitir UPDATEs.', 'Verifica sintaxis SQL antes de enviar sentencias a la base de datos.', 'Limpia la memoria del pool de conexiones tras cada petición web.', 'B', 'Senior', 'Hibernate detecta cambios comparando con el snapshot al hacer flush.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué efecto tiene activar el flag -XX:+UseStringDeduplication en la JVM?', 'Impide registrar usuarios con nombres duplicados en formularios.', 'Elimina cadenas repetidas en archivos de log en disco duro.', 'Hace que cadenas String idénticas compartan el mismo arreglo de bytes.', 'Convierte todas las cadenas a formato minúsculas en el heap.', 'C', 'Senior', 'Reduce el uso de memoria haciendo que cadenas iguales compartan char[]/byte[].', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué optimización aporta @Transactional(readOnly = true) con Hibernate?', 'Bloquea el motor impidiendo escrituras de cualquier otra sesión.', 'Envía consultas exclusivamente a réplicas de lectura de la base.', 'Desactiva la necesidad de abrir transacciones JDBC con el driver.', 'Evita guardar snapshots para Dirty Checking reduciendo consumo de CPU.', 'D', 'Senior', 'Al desactivar dirty checking y flushes innecesarios, ahorra memoria y cómputo.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Qué es el fenómeno de False Sharing en arquitecturas multiprocesador en Java?', 'Hilos en núcleos distintos invalidan cachés al modificar la misma línea.', 'Dos procesos comparten el mismo puerto TCP causando conflicto de red.', 'Variables estáticas son sobrescritas por librerías externas en la JVM.', 'El recolector de basura suspende hilos que no tienen referencias activas.', 'A', 'Senior', 'Ocurre cuando variables distintas residen en la misma línea de caché (64 bytes).', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cuál es el beneficio de compilar una aplicación Java con GraalVM Native Image?', 'Permite ejecutar la aplicación sin compilar el código fuente.', 'Arranque casi instantáneo y menor consumo de memoria RAM sin JIT.', 'Compatibilidad total con reflection sin necesidad de configuración.', 'Permite modificar el código en caliente sin detener el contenedor.', 'B', 'Senior', 'La compilación AOT genera binarios ultrarrápidos ideales para Serverless.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Por qué se especifica rollbackFor = Exception.class en @Transactional?', 'Para forzar el reinicio del servidor web ante cualquier excepción.', 'Para ignorar excepciones no verificadas y confirmar los cambios.', 'Para revertir la transacción también ante excepciones verificadas (checked).', 'Para registrar errores en un archivo de bitácora independiente en disco.', 'C', 'Senior', 'Por defecto Spring solo revierte ante RuntimeException y Error, no checked.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('java', '¿Cómo funciona la instrucción atómica Compare-And-Swap (CAS) en Java?', 'Bloquea todos los hilos del sistema operativo mientras actualiza.', 'Compara dos objetos y elimina el más antiguo para liberar memoria.', 'Copia el valor en disco duro antes de actualizar la variable en RAM.', 'Actualiza el valor en memoria solo si coincide con el valor esperado.', 'D', 'Senior', 'CAS actualiza a nivel de CPU sin bloqueos si el valor actual coincide.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Para qué sirve el hook useState en React?', 'Para agregar estado local a un componente funcional.', 'Para gestionar el estado global de toda la aplicación.', 'Para suscribirse a cambios en el DOM del navegador.', 'Para definir efectos secundarios después del renderizado.', 'A', 'Junior', 'useState retorna [valor, setter]; al llamar setter React re-renderiza el componente.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué hace useEffect en componentes funcionales de React?', 'Define variables de estado inmutables dentro del componente.', 'Ejecuta efectos secundarios después de que el componente ha renderizado.', 'Transforma funciones síncronas en procesos asíncronos automáticamente.', 'Compila JSX a código binario antes de que el navegador procese el DOM.', 'B', 'Junior', 'useEffect ejecuta suscripciones, timers y llamadas a APIs tras la actualización del DOM.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Cuál es la diferencia entre un componente controlado y uno no controlado?', 'Controlado: se renderiza en el servidor. No controlado: solo en el cliente.', 'Controlado: solo acepta props. No controlado: usa estado interno sin props.', 'Controlado: el estado del input lo maneja React. No controlado: lo maneja el DOM.', 'No hay diferencia funcional; es solo una convención de nomenclatura.', 'C', 'Junior', 'En inputs controlados React es la fuente de verdad; en no controlados se usa useRef.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Para qué se usa el hook useRef en React?', 'Para memorizar el resultado de funciones puras entre renderizados.', 'Para crear una copia del estado global accesible desde cualquier componente.', 'Para definir efectos secundarios con limpieza automática en el desmontaje.', 'Para mantener una referencia mutable que no dispara re-renderizados.', 'D', 'Junior', 'useRef.current persiste entre renders sin causar re-render; ideal para referencias al DOM.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Para qué sirve el hook useContext en React?', 'Para consumir valores de un Context sin necesidad de pasar props manualmente.', 'Para crear un contexto de ejecución asíncrono en el componente.', 'Para leer el contexto del navegador como idioma, zona horaria o resolución.', 'Para acceder al contexto de errores y capturar excepciones del árbol.', 'A', 'Junior', 'useContext(MiContexto) retorna el valor actual del proveedor más cercano en el árbol.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué hace React.StrictMode en una aplicación React?', 'Impide que los usuarios inspeccionen el código fuente con DevTools.', 'Activa advertencias adicionales y detecta efectos secundarios inesperados.', 'Fuerza que todos los componentes sean de tipo función (no clases).', 'Activa el modo de producción con optimizaciones de rendimiento máximas.', 'B', 'Junior', 'StrictMode ejecuta efectos dos veces en desarrollo para detectar dependencias ocultas.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Para qué sirve el archivo package.json en un proyecto React?', 'Configura las rutas de la aplicación para React Router.', 'Almacena el estado global de la aplicación en formato JSON.', 'Define metadatos, dependencias y scripts del proyecto Node.js/React.', 'Define los componentes globales registrados en la aplicación.', 'C', 'Junior', 'package.json tiene dependencies, devDependencies y scripts como start, build y test.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué hace el operador && en el renderizado condicional de React?', 'Verifica que ambos props sean válidos antes de renderizar el componente.', 'Aplica estilos CSS condicionalmente al elemento según el estado del componente.', 'Combina dos componentes en uno solo sin agregar nodos extra al DOM.', 'Renderiza el elemento del lado derecho solo si la condición izquierda es verdadera.', 'D', 'Junior', '{condicion && <Componente />} es el shorthand más común para renderizado condicional.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué hace el evento onSubmit en un formulario React?', 'Maneja el envío del formulario; se llama a e.preventDefault() para evitar recarga.', 'Valida automáticamente todos los campos del formulario en HTML5.', 'Envía los datos del formulario directamente a la URL definida en action.', 'Resetea todos los valores del formulario al estado inicial registrado.', 'A', 'Junior', 'e.preventDefault() en onSubmit evita la recarga; luego se procesan los datos del estado.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué hace el spread operator {...props} en JSX?', 'Fusiona el estado actual del padre con las props del componente hijo.', 'Pasa todas las propiedades de un objeto como props al componente hijo.', 'Extiende el componente con funcionalidades adicionales del HOC padre.', 'Copia el árbol DOM del componente a un nuevo nodo en la página.', 'B', 'Junior', '<Componente {...datos} /> equivale a <Componente a={datos.a} b={datos.b} ... />.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Cuándo deberías usar useReducer en lugar de useState?', 'Cuando el estado es un string simple que cambia con frecuencia.', 'Cuando el componente necesita compartir estado con componentes hermanos.', 'Cuando el estado tiene lógica compleja con múltiples transiciones relacionadas.', 'Cuando se necesita que el estado persista tras recargar la página.', 'C', 'Semi-Senior', 'useReducer(reducer, state) centraliza la lógica de actualización de estado complejo.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué es el Context API en React y cuándo se usa?', 'Define los endpoints de la API REST que el componente va a consumir.', 'Expone la API del navegador para acceder a la cámara y el micrófono.', 'Gestiona las llamadas HTTP del componente con cache automática.', 'Permite compartir datos entre componentes sin pasar props en cada nivel.', 'D', 'Semi-Senior', 'Context evita \"prop drilling\"; ideal para tema, idioma o usuario autenticado global.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué hace React.memo() y cuándo conviene usarlo?', 'HOC que evita re-renderizar un componente si sus props no cambiaron.', 'Almacena el resultado de las peticiones HTTP del componente en memoria.', 'Memoriza el árbol DOM del componente para animaciones más fluidas.', 'Crea una copia inmutable del estado para comparaciones de rendimiento.', 'A', 'Semi-Senior', 'memo() hace shallow comparison de props; úsalo en componentes puros con renders costosos.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué es React Router y cómo se implementa la navegación básica?', 'Sistema de routing integrado en React que no requiere instalación adicional.', 'Librería de enrutamiento; se usa <BrowserRouter>, <Routes> y <Route path>.', 'Plugin de Vite que genera rutas automáticamente basadas en el filesystem.', 'HOC que envuelve la app e inyecta el objeto history en todos los hijos.', 'B', 'Semi-Senior', 'react-router-dom v6 usa <Routes><Route path=\"/home\" element={<Home />} /></Routes>.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Cuándo se usa useLayoutEffect en lugar de useEffect?', 'Cuando el efecto depende del layout CSS calculado por el navegador.', 'Cuando el efecto debe ejecutarse antes del primer renderizado del componente.', 'Cuando se necesita leer o mutar el DOM antes de que el navegador pinte la pantalla.', 'Siempre que se hagan peticiones HTTP para evitar estados de carga visibles.', 'C', 'Semi-Senior', 'useLayoutEffect es síncrono tras mutaciones DOM; evita parpadeos al leer dimensiones.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué es el \"prop drilling\" y cómo se soluciona en React?', 'Renderizar props que contienen otros componentes en lugar de datos.', 'Usar demasiadas props en un componente; se resuelve con useReducer.', 'Pasar funciones como props que modifican el estado del componente padre.', 'Pasar props por muchos niveles sin que los intermedios las usen; se resuelve con Context.', 'D', 'Semi-Senior', 'Context API, Zustand o Redux eliminan prop drilling sin pasar por componentes intermedios.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué hace forwardRef en React?', 'Permite que un componente funcional acepte y reenvíe una ref al DOM interno.', 'Reenvía props de un componente padre a todos sus descendientes automáticamente.', 'Propaga los eventos del componente hijo hacia el componente padre.', 'Crea referencias compartidas entre componentes en diferentes árboles React.', 'A', 'Semi-Senior', 'forwardRef(fn) permite ref.current apuntar al elemento DOM interno del componente hijo.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué es el patrón \"render props\" en React?', 'Un conjunto de props que controlan qué parte del componente se renderiza.', 'Una prop que es una función y define qué renderizar con datos del componente.', 'Las props que React genera automáticamente al renderizar un componente.', 'Un patrón donde el padre inyecta componentes renderizados en el hijo.', 'B', 'Semi-Senior', '<Tracker render={(data) => <Display data={data} />} /> es el patrón render props clásico.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Cuál es la diferencia entre SPA (Single Page App) y SSR (Server Side Render)?', 'SSR es más lento para el usuario final porque el servidor hace más trabajo.', 'SPA usa múltiples páginas HTML; SSR usa una sola página con React.', 'SPA renderiza en el cliente; SSR genera el HTML en el servidor antes de enviar.', 'SPA solo funciona con React; SSR solo funciona con Next.js o Remix.', 'C', 'Semi-Senior', 'SSR mejora el FCP y SEO; SPA es más interactiva pero tiene TTFB más alto en primera carga.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué es Next.js y qué agrega sobre React puro?', 'Un gestor de estado avanzado que reemplaza Redux en proyectos grandes.', 'Una versión de React optimizada para dispositivos móviles y PWA.', 'Un framework CSS integrado con React que reemplaza Tailwind y styled-components.', 'Framework React con SSR, SSG, file-based routing, API routes y optimizaciones.', 'D', 'Semi-Senior', 'Next.js ofrece App Router, RSC, image optimization, fonts y API routes integradas.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Cómo se implementa la paginación infinita con React Query?', 'Con useInfiniteQuery que gestiona páginas, hasNextPage y fetchNextPage.', 'Con useQuery paginada llamando a setPage en un useEffect con IntersectionObserver.', 'Con usePagination de React Query que acumula los resultados de cada página.', 'Con un estado local y useEffect que detecta el scroll al final de la lista.', 'A', 'Senior', 'useInfiniteQuery(key, fn, { getNextPageParam }) acumula páginas y expone fetchNextPage.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué es el patrón \"Optimistic UI\" y cómo se implementa con React Query?', 'Mostrar un spinner optimista mientras la respuesta del servidor llega.', 'Actualizar el UI inmediatamente antes de confirmar la respuesta del servidor.', 'Cachear las respuestas del servidor para mostrarlas sin conexión a internet.', 'Predecir qué datos solicitará el usuario y pre-cargarlos en background.', 'B', 'Senior', 'useMutation con onMutate actualiza el cache; onError revierte si el servidor falla.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué son los Error Boundaries en React y cómo se implementan?', 'Bloques try/catch globales que React inyecta automáticamente en el árbol.', 'Hooks especiales que capturan excepciones en cualquier componente funcional.', 'Componentes de clase con componentDidCatch que capturan errores en hijos.', 'Middlewares de Redux que interceptan errores en las acciones dispatched.', 'C', 'Senior', 'Solo los componentes de clase pueden ser Error Boundaries vía getDerivedStateFromError.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué técnica de performance usa React al ejecutar múltiples setState juntos?', 'Memoization: cachea el estado anterior para compararlo con el nuevo.', 'Debouncing: espera un tiempo antes de procesar la última actualización.', 'Throttling: limita a una actualización por intervalo de tiempo definido.', 'Batching: agrupa múltiples actualizaciones en un solo re-renderizado.', 'D', 'Senior', 'React 18 hace automatic batching incluso en promesas y timeouts, reduciendo re-renders.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué es el patrón \"compound components\" en React?', 'Componentes relacionados que comparten estado implícito via Context internamente.', 'Componentes que se compilan juntos en un único bundle de producción.', 'Componentes que heredan de una clase base compartida con estado común.', 'Componentes que combinan múltiples hooks personalizados en uno solo.', 'A', 'Senior', 'Ejemplo: <Select><Select.Option/></Select> donde ambos comparten estado sin prop drilling.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Cuáles son las métricas Core Web Vitals relevantes para apps React?', 'TTI (tiempo de interactividad), FMP (primera pintura) y TBT (bloqueo).', 'LCP (carga), FID/INP (interactividad) y CLS (estabilidad visual).', 'TTFB (tiempo primer byte), FCP (primer contenido) y SI (speed index).', 'Bundle size, número de re-renders y tiempo de hidratación del HTML.', 'B', 'Senior', 'LCP, INP (antes FID) y CLS son las métricas de Google que afectan el ranking SEO real.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Cómo funciona el Server-Side Rendering de Next.js con getServerSideProps?', 'Pre-renderiza solo la estructura HTML y los datos los carga el cliente.', 'Genera HTML estático en build-time y lo sirve desde CDN sin servidor.', 'Ejecuta en cada request: fetches datos en servidor y los pasa como props a la página.', 'Ejecuta una sola vez en el arranque del servidor y cachea el resultado.', 'C', 'Senior', 'getServerSideProps corre por cada request (SSR); getStaticProps corre en build (SSG).', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué son los React DevTools y qué información permiten ver?', 'Panel en el servidor para monitorear renders remotos en producción.', 'Herramientas de línea de comandos para analizar el bundle de producción.', 'Plugin de VS Code para debuggear componentes React sin navegador.', 'Extensión del navegador para inspeccionar el árbol de componentes, props y estado.', 'D', 'Senior', 'React DevTools muestra el árbol, props, hooks, estado y el Profiler para medir renders.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué son las \"islands architecture\" (islas) y cómo se relaciona con React?', 'HTML estático con \"islas\" de interactividad React; reduce el JS enviado al cliente.', 'Componentes React aislados que no pueden comunicarse con otros componentes.', 'Módulos de React que se ejecutan en servidores distribuidos geográficamente.', 'Fragmentos del bundle que solo se cargan cuando el usuario los solicita.', 'A', 'Senior', 'Frameworks como Astro usan islas; solo los componentes interactivos envían JS al browser.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué problema resuelve el patrón \"state machine\" con XState en React?', 'Persiste el estado del componente en una máquina de estados del servidor.', 'Gestiona estados finitos complejos eliminando lógica condicional dispersa.', 'Optimiza el rendimiento de componentes con muchas transiciones de estado.', 'Sincroniza el estado entre múltiples instancias de React en tabs distintas.', 'B', 'Senior', 'XState modela flujos como: idle→loading→success|error; elimina bugs de estados imposibles.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué hook maneja el estado local?', 'useRef', 'useEffect', 'useState', 'useMemo', 'C', 'Junior', 'useState crea estado local.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué hook ejecuta efectos secundarios?', 'useState', 'useMemo', 'useRef', 'useEffect', 'D', 'Semi-Senior', 'useEffect maneja efectos secundarios.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué método de ciclo de vida equivale a useEffect con array vacío?', 'componentDidMount', 'render', 'componentWillUnmount', 'constructor', 'A', 'Senior', 'componentDidMount se ejecuta una vez.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué prop especial permite renderizar elementos hijos?', 'props', 'children', 'elements', 'nodes', 'B', 'Junior', 'La prop children pasa componentes hijos.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Cómo se actualiza el estado basado en el estado anterior?', 'state = state + 1', 'setState(state + 1)', 'setState(prev => prev + 1)', 'this.state++', 'C', 'Semi-Senior', 'Se usa una función callback en setState.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué hook memoriza un valor calculado?', 'useState', 'useCallback', 'useRef', 'useMemo', 'D', 'Senior', 'useMemo cachea valores calculados.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué hook memoriza una función?', 'useCallback', 'useMemo', 'useRef', 'useEffect', 'A', 'Junior', 'useCallback cachea referencias a funciones.', 1);
