INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué estado global es muy popular en React?', 'Redux', 'Axios', 'Jest', 'Enzyme', 'A', 'Semi-Senior', 'Redux maneja el estado global complejo.', 1);
