INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué función compara el Virtual DOM con el real?', 'Rendering', 'Diffing', 'Reconciliation', 'Mounting', 'C', 'Semi-Senior', 'El proceso se llama Reconciliación.', 1);
