INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué framework usa React para SSR?', 'Next.js', 'Create React App', 'Gatsby', 'Vite', 'A', 'Junior', 'Next.js permite renderizado en servidor.', 1);
