INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué atributo es obligatorio al iterar listas en JSX?', 'index', 'id', 'key', 'ref', 'C', 'Senior', 'La key ayuda a React a identificar elementos.', 1);
