INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('react', '¿Qué patrón renderiza props como funciones?', 'HOC', 'Render Props', 'Hooks', 'Context', 'B', 'Senior', 'Render Props inyecta datos dinámicos.', 1);
