INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué indica PIC X(20) en COBOL?', 'Un campo numérico de 20 dígitos.', 'Un campo alfanumérico de 20 caracteres.', 'Una tabla de 20 campos numéricos.', 'Un campo con valor hexadecimal de 20 bytes.', 'B', 'Junior', 'X en PIC indica alfanumérico; X(20) reserva 20 bytes de almacenamiento.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué verbo COBOL se usa para llamar a un subprograma externo?', 'EXECUTE nombre-modulo.', 'INVOKE nombre-modulo.', 'CALL nombre-modulo.', 'RUN nombre-modulo.', 'C', 'Junior', 'CALL invoca un subprograma pasando parámetros mediante la cláusula USING.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Cuándo se activa la cláusula AT END en un verbo READ?', 'Cuando el archivo supera el tamaño máximo permitido.', 'Cuando hay un error de E/S al intentar leer el archivo.', 'Cuando el registro leído tiene todos los campos en cero.', 'Cuando se ha leído el último registro y no hay más datos.', 'D', 'Junior', 'AT END (EOF) se dispara cuando READ no encuentra más registros; permite el fin de ciclo.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué hace la cláusula CORRESPONDING (CORR) en COBOL?', 'Mueve o suma campos con el mismo nombre entre dos grupos.', 'Copia la estructura completa de un copybook al programa.', 'Compara dos registros campo a campo y retorna diferencias.', 'Define correspondencias entre variables y campos de DB2.', 'A', 'Junior', 'MOVE CORRESPONDING mueve los campos de mismo nombre de origen a destino automáticamente.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué función tiene FILE STATUS en COBOL?', 'Muestra el nombre del archivo actualmente abierto en el panel de control.', 'Almacena un código de dos caracteres con el resultado de la última operación de IO.', 'Define el tamaño máximo del archivo en bytes antes de la apertura.', 'Indica el número de registros escritos desde la última apertura del archivo.', 'B', 'Junior', 'FILE STATUS retorna \"00\" (éxito), \"10\" (EOF), \"23\" (no encontrado) tras cada operación IO.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Para qué sirve la sentencia //DD en JCL?', 'Declarar el número de procesadores asignados al trabajo.', 'Definir las variables de entorno para el paso de ejecución.', 'Asociar el nombre lógico del archivo COBOL (DDNAME) con el dataset físico.', 'Especificar las prioridades de impresión del paso batch.', 'C', 'Junior', '//DD enlaza el SELECT...ASSIGN del programa con el dataset real mediante el parámetro DSN.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué hace DISP=(NEW,CATLG,DELETE) en un DD de JCL?', 'Crea el dataset temporal, lo pasa al siguiente paso y lo elimina al terminar.', 'Lee un dataset nuevo, lo cataloga siempre y lo borra al final.', 'Abre el dataset existente, no lo cataloga y lo retiene sin importar el resultado.', 'Crea el dataset, lo cataloga si el job termina bien, o lo borra si falla.', 'D', 'Junior', 'Los tres subparámetros son: estado-inicial, disposición-normal y disposición-anormal.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué es un dataset temporal en JCL y cómo se identifica?', 'Un dataset con nombre que empieza por && que se borra al terminar el job.', 'Un dataset con nombre que empieza por ## usado como trabajo permanente.', 'Un dataset sin DSN que persiste en disco aunque el job falle.', 'Un dataset catalogado con atributo TEMP que caduca en 7 días.', 'A', 'Junior', 'Los datasets temporales (&&nombre) son automáticamente eliminados al terminar el job.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Cuál es la función del programa IEFBR14 en JCL?', 'Ordena los registros de un dataset según campos definidos en tarjetas SYSIN.', 'No hace nada; se usa para crear o borrar datasets mediante las DDs del paso.', 'Copia un dataset completo de origen a destino sin modificación.', 'Genera un listado de todos los datasets catalogados en el volumen.', 'B', 'Junior', 'IEFBR14 solo retorna RC=0; su utilidad es que JCL procesa los DDs: crea/borra datasets.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué hace el programa IEBGENER en JCL?', 'Crea catálogos del sistema en el volumen de disco especificado.', 'Genera claves primarias para registros de datasets VSAM KSDS.', 'Copia un dataset secuencial de SYSUT1 a SYSUT2 registro por registro.', 'Imprime el contenido hexadecimal de cualquier tipo de dataset.', 'C', 'Junior', 'IEBGENER copia archivos secuenciales; SYSUT1=entrada, SYSUT2=salida, SYSIN=DD DUMMY.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué hace la cláusula REDEFINES en la DATA DIVISION de COBOL?', 'Elimina un campo de la memoria liberando su espacio de almacenamiento.', 'Cambia el nombre de un campo en el diccionario de datos del sistema.', 'Convierte automáticamente un campo numérico en texto Unicode.', 'Permite que diferentes descripciones compartan el mismo espacio de memoria.', 'D', 'Semi-Senior', 'REDEFINES superpone dos estructuras en el mismo bloque de memoria sin duplicar espacio.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Cuál es la diferencia entre SEARCH y SEARCH ALL en tablas COBOL?', 'SEARCH es lineal O(n); SEARCH ALL es binario O(log n) y requiere tabla ordenada.', 'SEARCH busca texto; SEARCH ALL busca exclusivamente valores numéricos.', 'SEARCH ALL modifica la tabla eliminando duplicados durante la búsqueda.', 'No hay diferencia funcional; es solo preferencia de estilo de código.', 'A', 'Semi-Senior', 'SEARCH ALL requiere ASCENDING/DESCENDING KEY definida en OCCURS y tabla ya ordenada.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué indica OCCURS 10 TIMES INDEXED BY WS-IDX en COBOL?', 'Repite la sección del programa exactamente 10 veces de forma automática.', 'Define una tabla de 10 elementos accesibles mediante el índice WS-IDX.', 'Crea 10 archivos separados con el mismo layout de registro.', 'Indica que el campo puede aparecer entre 1 y 10 veces en el registro.', 'B', 'Semi-Senior', 'OCCURS con INDEXED BY usa un valor de índice interno (no subíndice) para acceso eficiente.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Cuándo se usa OCCURS DEPENDING ON en COBOL?', 'Para indicar que la tabla solo existe si una condición es verdadera.', 'Para definir tablas que dependen de la versión del compilador instalado.', 'Para definir tablas de longitud variable cuyo tamaño se determina en tiempo de ejecución.', 'Para tablas cuyos elementos se cargan desde un archivo VSAM externo.', 'C', 'Semi-Senior', 'ODO permite tablas de hasta OCCURS MAX TIMES donde el recuento real está en otro campo.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué significa un FILE-STATUS \"23\" en COBOL?', 'El archivo fue abierto por otro programa con modo exclusivo (OLD).', 'El archivo tiene 23 registros menos de los esperados por el programa.', 'Se produjo un error de E/S irrecuperable en el dispositivo de almacenamiento.', 'No se encontró el registro solicitado (KEY NOT FOUND) en un archivo indexado.', 'D', 'Semi-Senior', '\"23\" es \"Record Not Found\" en archivos con acceso directo (VSAM KSDS, RRDS).', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué hace EVALUATE TRUE en COBOL?', 'Evalúa una serie de condiciones y ejecuta el caso cuya condición sea verdadera.', 'Verifica que todas las variables de la sección sean inicialmente verdaderas.', 'Fuerza al compilador a optimizar el código eliminando ramas muertas.', 'Comprueba la integridad de los datos antes de procesarlos.', 'A', 'Semi-Senior', 'EVALUATE TRUE ... WHEN condición es el equivalente moderno de IF/ELSE-IF encadenados.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Cuál es la función de INITIALIZE en COBOL?', 'Abre todos los archivos declarados en la FILE SECTION simultáneamente.', 'Pone a cero los numéricos y espacios los alfanuméricos de un grupo o variable.', 'Crea e inicializa las tablas internas con valores predeterminados del sistema.', 'Reinicia el contador de registros procesados al inicio de cada ciclo.', 'B', 'Semi-Senior', 'INITIALIZE equivale a MOVE ZEROS/SPACES al grupo completo, incluyendo subelementos.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué hace STRING en COBOL?', 'Compara dos cadenas y retorna la más corta como resultado.', 'Convierte una cadena de texto en una estructura de campos numéricos.', 'Concatena varias cadenas o campos en una sola variable destino.', 'Define un campo de longitud variable terminado en un delimitador especial.', 'C', 'Semi-Senior', 'STRING permite unir múltiples campos con delimitadores opcionales en una sola variable.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué hace el verbo INSPECT en COBOL?', 'Genera un informe de auditoría de todas las lecturas del archivo de entrada.', 'Valida la estructura de un registro contra el layout definido en FILE SECTION.', 'Imprime en SYSOUT el contenido actual de todas las variables del grupo.', 'Cuenta o reemplaza ocurrencias de caracteres o cadenas en una variable.', 'D', 'Semi-Senior', 'INSPECT ... TALLYING cuenta ocurrencias; INSPECT ... REPLACING sustituye caracteres.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué ventaja tiene COMP-3 (PACKED-DECIMAL) sobre DISPLAY en COBOL?', 'Guarda 2 dígitos por byte ahorrando espacio y permite operaciones rápidas.', 'Permite almacenar hasta el doble de dígitos en el mismo espacio.', 'Elimina la necesidad del signo en cálculos matemáticos positivos.', 'Solo funciona con DB2 y no puede usarse en archivos secuenciales.', 'A', 'Semi-Senior', 'COMP-3 (PACKED) almacena 2 dígitos por byte más un nibble de signo, optimizando espacio.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Cuándo se usa la sentencia EXEC SQL en COBOL?', 'Para ejecutar scripts de administración de base de datos del mainframe.', 'Para embeber sentencias SQL de DB2 directamente en el programa COBOL.', 'Para llamar módulos de acceso a VSAM mediante la interfaz SQL.', 'Para declarar variables de host que usará el precompilador DB2.', 'B', 'Semi-Senior', 'EXEC SQL ... END-EXEC embebe SQL; el precompilador DB2 lo transforma en llamadas CALL.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué es el SQLCA y qué campo se revisa tras cada EXEC SQL?', 'SQL Count Area; se revisa SQLN para conocer las filas afectadas.', 'SQL Control Area; se revisa SQLSTATE para ver el mensaje de texto del error.', 'SQL Communication Area; se revisa SQLCODE (0=OK, +100=no encontrado, negativo=error).', 'SQL Cache Area; se revisa SQLRCODE para validar el plan de acceso.', 'C', 'Semi-Senior', 'SQLCA (include SQLCA) provee SQLCODE; 0=éxito, +100=EOF, negativo=error DB2.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué hace el verbo EXEC CICS SEND MAP en un programa COBOL CICS?', 'Manda un mensaje de error al log del sistema CICS JES.', 'Transfiere datos a la cola CICS para procesamiento asíncrono.', 'Envía el registro procesado al archivo VSAM indicado en el MAP.', 'Envía un mapa (pantalla BMS) al terminal del usuario para mostrar datos.', 'D', 'Semi-Senior', 'SEND MAP presenta la pantalla BMS con los datos del MAPSET al terminal 3270.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué sentencias JCL reemplazan la compleja lógica COND para flujo condicional?', 'Las sentencias // IF / THEN / ELSE / ENDIF basadas en RC o ABEND.', 'Las sentencias //WHEN y //OTHERWISE del sistema JES3.', 'Los bloques //CASE y //ESAC disponibles en versiones z/OS recientes.', 'Las directivas //CHECK y //SKIP del compilador de procedimientos.', 'A', 'Semi-Senior', '// IF (STEP1.RC = 0) THEN ... // ENDIF es más legible que la antigua sintaxis COND.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué significa COND=EVEN en una sentencia //EXEC de JCL?', 'El paso se ejecuta solo cuando el código de retorno previo es par.', 'El paso se ejecuta aunque pasos anteriores hayan terminado con ABEND.', 'El paso se ejecuta únicamente en LPAR con número de CPU par.', 'El paso se ejecuta si el job anterior en la cadena finalizó correctamente.', 'B', 'Semi-Senior', 'COND=EVEN ejecuta el paso incluso si hubo ABEND previo; útil para limpieza de recursos.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué hace el programa IDCAMS en JCL?', 'Copia módulos de carga entre bibliotecas PDS del sistema.', 'Ordena registros de datasets secuenciales en orden ascendente o descendente.', 'Administra datasets VSAM: crea, borra, lista, copia y repara catálogos.', 'Genera reportes de espacio disponible en los volúmenes DASD del sistema.', 'C', 'Semi-Senior', 'IDCAMS es el Access Method Services; procesa comandos como DEFINE CLUSTER, DELETE, REPRO.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Para qué se usa DFSORT en JCL y cuál es su DD principal de control?', 'Filtra registros de DB2; las condiciones van en el DD SORTWORK.', 'Genera datasets de diagnóstico; las opciones se pasan en el DD SORTOUT.', 'Copia datasets con transformación; las reglas van en el DD SYSUT1.', 'Ordena o mezcla datasets; las tarjetas de control van en el DD SORTIN/SYSIN.', 'D', 'Semi-Senior', 'DFSORT usa SORTIN (entrada), SORTOUT (salida) y SYSIN (tarjetas SORT FIELDS= o INCLUDE=).', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué hace el parámetro RESTART en una sentencia //JOB de JCL?', 'Reinicia el job desde un paso específico sin reejecutar los pasos anteriores.', 'Reinicia automáticamente el job desde el inicio en caso de error o ABEND.', 'Activa el módulo de checkpoint para guardar el estado cada N registros.', 'Transfiere el job a una clase diferente de ejecución al reiniciar.', 'A', 'Semi-Senior', 'RESTART=nombre-paso permite reanudar desde ese paso sin repetir los completados.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué hace el parámetro REGION en una sentencia //JOB o //EXEC de JCL?', 'Indica la región geográfica del centro de datos donde se ejecuta el job.', 'Define la cantidad máxima de memoria virtual asignada al job o paso.', 'Especifica el número de región de CICS a la que se conecta el programa.', 'Define el área de memoria compartida entre los pasos del mismo job.', 'B', 'Semi-Senior', 'REGION=128M asigna hasta 128MB al job/paso; si se excede ocurre S80A o S878 ABEND.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué parámetro TIME en JCL limita el tiempo de CPU de un paso?', 'TIME=(horas,minutos) define la hora del día en que el paso debe iniciar.', 'TIME=NOLIMIT indica que el paso puede ejecutarse sin restricción de tiempo.', 'TIME=(minutos,segundos) establece el límite de CPU antes de generar S322.', 'TIME=MAX asigna el máximo de tiempo de CPU disponible en la clase.', 'C', 'Semi-Senior', 'Si el paso supera el TIME definido, z/OS genera ABEND S322 (tiempo de CPU excedido).', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué es un ABEND S0C7 en un programa COBOL corriendo en z/OS?', 'Open Error: el programa intentó leer un archivo que no existe en el catálogo.', 'Storage Violation: el programa accedió a memoria fuera de su región asignada.', 'Time Exceeded: el programa superó el tiempo de CPU máximo del paso.', 'Data Exception: operación aritmética con datos no numéricos en campo numérico.', 'D', 'Semi-Senior', 'S0C7 ocurre cuando se opera aritmética sobre un campo DISPLAY con espacios o caracteres.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Cuál es la diferencia entre un PDS y un PDSE en z/OS?', 'PDSE permite miembros de tamaño variable y no requiere compactación periódica.', 'PDSE solo almacena módulos de carga mientras PDS almacena cualquier tipo.', 'PDS admite más de 200 miembros activos mientras PDSE está limitado a 10.', 'No hay diferencia funcional; PDSE es solo el nombre moderno de PDS.', 'A', 'Semi-Senior', 'PDSE elimina la necesidad de IEBCOPY/compress; gestiona espacio libre automáticamente.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Cómo se declara un cursor DB2 en COBOL y cuándo se usa OPEN CURSOR?', 'Con EXEC SQL CREATE CURSOR en WORKING-STORAGE; se abre con EXEC CICS OPEN.', 'Con EXEC SQL DECLARE cursor CURSOR FOR SELECT; se abre con EXEC SQL OPEN cursor.', 'Con un SELECT simple en EXEC SQL; el cursor se abre automáticamente.', 'Con EXEC SQL DEFINE CURSOR al inicio de PROCEDURE DIVISION.', 'B', 'Senior', 'DECLARE define el cursor; OPEN lo materializa; FETCH recupera fila por fila; CLOSE libera.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué es un deadlock en DB2 y cómo se maneja en COBOL?', 'Un error de sintaxis SQL que el precompilador detecta en tiempo de compilación.', 'Un timeout de red que DB2 detecta y retorna SQLCODE -922 al programa.', 'Bloqueo circular entre transacciones; DB2 aborta una y retorna SQLCODE -911.', 'Una condición de espera en CICS cuando dos transacciones leen el mismo mapa.', 'C', 'Senior', 'SQLCODE -911 (deadlock) o -913 (timeout) requieren ROLLBACK y reintentar la transacción.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué hace EXEC CICS SYNCPOINT en un programa CICS COBOL?', 'Guarda el estado de la pantalla 3270 en una cola temporal para recuperación.', 'Sincroniza los relojes de sistema entre el LPAR principal y el de backup.', 'Hace una pausa y espera a que otra transacción CICS libere un recurso.', 'Confirma (commit) todos los cambios de la unidad de trabajo actual en CICS.', 'D', 'Senior', 'SYNCPOINT es el COMMIT de CICS; SYNCPOINT ROLLBACK deshace los cambios de la UOW.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué es el COMMAREA en CICS y cómo se pasa entre transacciones?', 'Un área de datos compartida que se pasa con EXEC CICS RETURN TRANSID COMMAREA.', 'Una cola de mensajes de sistema que CICS mantiene entre todas las transacciones.', 'Una tabla de control que almacena los mapas BMS del sistema de pantallas.', 'Un archivo VSAM temporal que contiene el estado de la sesión del usuario.', 'A', 'Senior', 'COMMAREA (hasta 32KB) se pasa entre pseudo-conversaciones via EXEC CICS RETURN COMMAREA.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué técnica permite a COBOL procesar registros con ABEND S0C7 y continuar?', 'Usar USAGE COMP-1 en todos los campos para prevenir errores de datos.', 'Implementar una rutina ON EXCEPTION o verificar FILE-STATUS y SQLCODE.', 'Agregar EXCEPTION HANDLING con TRY/CATCH como en Java o C#.', 'Declarar todos los campos numéricos como PIC X para evitar data exceptions.', 'B', 'Senior', 'COBOL no tiene excepciones; se validan datos con IF NUMERIC antes de operar y FILE-STATUS.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué es el programa DSNUPROC en el contexto de DB2 batch COBOL?', 'Un procedimiento CICS que gestiona la conexión entre CICS y DB2.', 'El módulo principal que compila y precompila programas COBOL con DB2.', 'El procedimiento de utilidades DB2 para RUNSTATS, REORG, LOAD y CHECK.', 'La rutina de instalación del catálogo DB2 en el volumen de sistema.', 'C', 'Senior', 'DSNUPROC ejecuta utilidades como RUNSTATS (estadísticas), REORG (reorganización) y LOAD.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué diferencia hay entre REWRITE y WRITE en un archivo VSAM COBOL?', 'No hay diferencia; ambos verbos modifican registros del archivo VSAM.', 'WRITE es más eficiente que REWRITE para grandes volúmenes de datos VSAM.', 'REWRITE puede insertar o actualizar; WRITE solo inserta en KSDS.', 'REWRITE actualiza un registro existente ya leído; WRITE inserta un registro nuevo.', 'D', 'Senior', 'REWRITE actualiza el registro previamente leído con READ UPDATE; WRITE agrega uno nuevo.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué hace la cláusula WITH HOLD en un cursor DB2 de COBOL?', 'Mantiene el cursor abierto tras un COMMIT sin necesidad de reabrirlo.', 'Bloquea la tabla completa durante toda la vida del cursor.', 'Impide que otros programas accedan al mismo plan de acceso DB2.', 'Retiene los locks de fila hasta el final de la transacción CICS.', 'A', 'Senior', 'WITH HOLD preserva el cursor tras COMMIT; sin él el cursor se cierra automáticamente.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué hace el verbo EXEC CICS LINK en COBOL CICS?', 'Enlaza un módulo externo a la memoria del task actual de CICS.', 'Llama a otro programa CICS pasando control y COMMAREA, retornando al llamador.', 'Crea un link de datos entre dos colas temporales de CICS.', 'Inicia una nueva transacción CICS de forma asíncrona sin esperar respuesta.', 'B', 'Senior', 'EXEC CICS LINK invoca un subprograma y retorna; XCTL transfiere sin retorno al llamador.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué diferencia hay entre EXEC CICS LINK y EXEC CICS XCTL?', 'XCTL permite pasar COMMAREA mayor de 32KB; LINK está limitado a 32KB.', 'LINK es para módulos ASSEMBLER; XCTL es exclusivo para programas COBOL.', 'LINK retorna al programa llamador; XCTL transfiere el control sin retorno.', 'No hay diferencia práctica; ambos terminan la tarea CICS actual.', 'C', 'Senior', 'LINK es como CALL (retorna); XCTL es como GO TO a otro programa (no retorna al llamador).', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Cómo se implementa manejo de errores robusto en programas COBOL DB2 batch?', 'Activar el parámetro SQLCHECK=ALL en el JCL de compilación de DB2.', 'Envolver cada EXEC SQL en un bloque TRY/CATCH de la extensión OO-COBOL.', 'Usar FILE-STATUS para capturar errores SQL igual que en archivos VSAM.', 'Verificar SQLCODE tras cada EXEC SQL; usar WHENEVER SQLERROR GO TO rutina.', 'D', 'Senior', 'WHENEVER SQLERROR GO TO rutina-error centraliza el manejo; luego revisa SQLCODE/SQLERRM.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué hace EXEC CICS WRITEQ TS en COBOL?', 'Escribe un item en una cola temporal (Temporary Storage) de CICS.', 'Escribe un registro en el archivo VSAM de la transacción actual.', 'Envía un mensaje de texto al terminal del usuario mediante la cola JES.', 'Registra una entrada en el log de auditoría del sistema CICS.', 'A', 'Senior', 'Temporary Storage Queue (TSQ) es como memoria compartida entre tasks CICS; TS es efímera.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué hace el comando IDCAMS REPRO en JCL?', 'Repara la estructura de índices de un VSAM KSDS dañado.', 'Copia registros de un dataset (VSAM o secuencial) a otro dataset destino.', 'Genera un reporte de diagnóstico del estado del catálogo VSAM.', 'Reproduce la ejecución de un job anterior usando los mismos parámetros.', 'B', 'Senior', 'REPRO copia datos; puede cargar datos secuenciales en VSAM o copiar entre VSAM clusters.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué diferencia tiene EXEC SQL FETCH con FOR n ROWS en DB2 COBOL?', 'Saltea n filas antes de retornar la primera fila del cursor.', 'Limita el número máximo de filas que el cursor puede devolver en total.', 'Permite recuperar múltiples filas en un solo FETCH usando un array host variable.', 'Actualiza n filas del resultado del cursor en una sola operación.', 'C', 'Senior', 'FETCH n ROWS (multi-row fetch) reduce las llamadas a DB2 y mejora performance en batch.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué es el COBOL precompiler y qué genera como salida?', 'Traduce COBOL a ASSEMBLER para optimización previa a la compilación.', 'Genera código binario ejecutable directamente sin pasar por el compilador.', 'Produce un listado de los errores de SQL sin modificar el fuente COBOL.', 'Traduce EXEC SQL a llamadas CALL DSN... en COBOL puro para el compilador.', 'D', 'Senior', 'El precompilador DB2 sustituye EXEC SQL por CALL DSNHLI y genera el DBRM para el BIND.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué hace el comando IDCAMS DEFINE CLUSTER en JCL?', 'Crea un dataset VSAM especificando tipo (KSDS/ESDS/RRDS), espacio y clave.', 'Define un grupo de jobs relacionados que comparten el mismo espacio DASD.', 'Crea una biblioteca PDS con directorio de N bloques para miembros.', 'Establece un clúster de procesadores para paralelizar el job batch.', 'A', 'Senior', 'DEFINE CLUSTER(NAME(...) INDEXED KEYS(...) CYL(...)) crea el VSAM con sus componentes.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Cómo se sobrescribe un DD de un PROC catalogado desde el JCL del job?', 'Editando directamente el miembro del PROC en SYS1.PROCLIB antes del job.', 'Codificando //nombre-paso.nombre-DD DD DSN=... después del //EXEC PROC.', 'Usando el parámetro OVERRIDE=DD en la sentencia //EXEC PROC.', 'Agregando un DD con DISP=OLD después del // END del PROC en el stream.', 'B', 'Senior', '//PASO.DDNAME DD DSN=nuevo-dataset sobrescribe el DD definido dentro del PROC catalogado.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué hace el programa DFSORT con la tarjeta de control INCLUDE COND?', 'Agrega los registros del dataset SORTIN2 basándose en una condición de campo.', 'Incluye el dataset de control adicional en la entrada del sort.', 'Solo incluye en la salida los registros que cumplen la condición especificada.', 'Fuerza la inclusión de registros duplicados que normalmente serían omitidos.', 'C', 'Senior', 'INCLUDE COND=(pos,len,tipo,op,valor) filtra registros antes del ordenamiento o copia.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué es la clase de trabajo (CLASS) en JCL y cómo afecta la ejecución?', 'Define la clase de almacenamiento DASD donde se crean los datasets del job.', 'Determina la clase de seguridad RACF que controla el acceso a los datasets.', 'Indica la clase de error (ABEND) que el job reportará al operador del sistema.', 'Define en qué iniciadores (initiators) puede correr el job según prioridad y recursos.', 'D', 'Senior', 'La CLASS conecta el job con iniciadores específicos del JES que tienen recursos definidos.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué hace la utilidad IEBCOPY en JCL?', 'Copia, fusiona, selecciona o excluye miembros de datasets particionados (PDS/PDSE).', 'Genera copias de seguridad de datasets secuenciales en cinta magnética.', 'Copia registros entre datasets VSAM usando la interfaz de control SYSIN.', 'Compacta el directorio de un PDS eliminando entradas de miembros borrados.', 'A', 'Senior', 'IEBCOPY COPY/SELECT/EXCLUDE gestiona miembros de PDS; también compacta con COMPRESS.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Cuál es el propósito principal del parámetro SPACE en JCL?', 'Añadir espacios en blanco al archivo.', 'Definir el espacio en disco a asignar a un data set.', 'Indicar la memoria RAM máxima del job.', 'Configurar los espacios de tabulación del código.', 'B', 'Senior', 'SPACE asigna cilindros, tracks o bloques en disco.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué cláusula de COBOL cierra un archivo 1?', 'EXIT', 'END', 'CLOSE', 'STOP', 'C', 'Junior', 'CLOSE termina el procesamiento del archivo.', 1);
