INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cobol', '¿Qué cláusula de COBOL cierra un archivo 38?', 'STOP', 'END', 'EXIT', 'CLOSE', 'D', 'Junior', 'CLOSE termina el procesamiento del archivo.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cuál es la extensión de un archivo fuente en Informix 4GL?', '.4gl', '.igl', '.ifx', '.sql', 'A', 'Junior', 'Los programas 4GL se guardan con extensión .4gl y se compilan con el comando c4gl.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cómo se declara una variable en Informix 4GL?', 'Con la palabra reservada VAR nombre AS tipo al inicio del módulo.', 'Con la cláusula DEFINE nombre tipo en la sección de declaraciones.', 'Con DECLARE nombre tipo antes de cada función del programa.', 'Con DIM nombre AS tipo dentro del bloque MAIN del programa.', 'B', 'Junior', 'DEFINE es la palabra clave para variables locales y de módulo en Informix 4GL.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué hace la sentencia LET en Informix 4GL?', 'Define una constante inmutable en el bloque de declaraciones.', 'Declara y asigna una variable en una sola línea de código.', 'Asigna un valor a una variable: LET var = expresion.', 'Ejecuta una expresión SQL y guarda el resultado en una variable.', 'C', 'Junior', 'LET es el operador de asignación principal de 4GL; equivale a = en otros lenguajes.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cuál es la estructura básica de un programa Informix 4GL?', 'MODULE, DEFINE, BEGIN WORK...COMMIT con bloques EXCEPTION.', 'PROGRAM, VARIABLES, BEGIN...END con subrutinas CALL externas.', 'SCHEMA, DECLARATIONS, PROCEDURE...END PROCEDURE con cursores.', 'DATABASE, DEFINE globales, MAIN...END MAIN con FUNCTIONs/REPORTs.', 'D', 'Junior', 'Un programa 4GL tiene DATABASE db, DEFINE vars, MAIN...END MAIN y FUNCTIONs opcionales.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué hace DATABASE nombre_bd al inicio de un programa 4GL?', 'Conecta el programa a la base de datos Informix especificada.', 'Crea una nueva base de datos con el nombre especificado en el servidor.', 'Declara el esquema de la base de datos para uso del precompilador.', 'Define los permisos de acceso a las tablas de la base de datos.', 'A', 'Junior', 'DATABASE conecta al servidor; puede usarse DISCONNECT para cerrar la conexión.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cómo se ejecuta una consulta SELECT simple en Informix 4GL?', 'EXEC SQL SELECT col FROM tabla WHERE condicion INTO var.', 'SELECT col INTO var FROM tabla WHERE condicion.', 'FETCH nombre_cursor INTO var para cada SELECT del programa.', 'QUERY col FROM tabla WHERE condicion RETURNING var.', 'B', 'Junior', 'El SELECT ... INTO var FROM ... es la forma directa para una sola fila en 4GL.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué hace la variable STATUS en Informix 4GL?', 'Almacena el número de filas afectadas por el último SQL ejecutado.', 'Indica el estado de la conexión actual con el servidor Informix.', 'Contiene el código de error de la última operación de base de datos.', 'Guarda el estado del formulario de pantalla actual del programa.', 'C', 'Junior', 'STATUS = 0 indica éxito; NOTFOUND es 100; valores negativos son errores de Informix.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué es un cursor en Informix 4GL?', 'Un índice de tabla que optimiza la búsqueda de registros por clave.', 'El puntero del ratón en las pantallas de interfaz de usuario 4GL.', 'Un tipo de variable especial para almacenar blobs de texto largo.', 'Un nombre que representa una consulta SELECT para iterar múltiples filas.', 'D', 'Junior', 'DECLARE cursor CURSOR FOR SELECT ...; se usa OPEN, FETCH y CLOSE para iterar filas.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué hace OPEN cursor_name en Informix 4GL?', 'Ejecuta la consulta y posiciona el cursor antes del primer registro.', 'Abre el archivo de definición del cursor almacenado en disco.', 'Conecta el cursor con la tabla y bloquea todos sus registros.', 'Abre una ventana de pantalla asociada al cursor de datos.', 'A', 'Junior', 'OPEN ejecuta el SELECT subyacente; FETCH recupera fila por fila hasta STATUS = NOTFOUND.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cuál es la estructura básica para iterar sobre un cursor en 4GL?', 'FOR EACH ROW IN c1 ... NEXT ROW; END FOR.', 'OPEN c1; FETCH c1 INTO vars; WHILE STATUS=0 ... FETCH c1 INTO vars; END WHILE; CLOSE c1.', 'LOOP c1 FETCH INTO vars WHILE NOT EOF; END LOOP.', 'FOREACH cursor_name INTO vars ... CONTINUE FOREACH; END FOREACH.', 'B', 'Junior', 'El patrón estándar: OPEN, FETCH, WHILE STATUS=0, procesar, FETCH, END WHILE, CLOSE.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué es SQLCA en Informix 4GL?', 'El archivo de configuración de la conexión con el servidor Informix.', 'La tabla del catálogo del sistema donde se almacenan los esquemas.', 'La estructura de comunicación SQL que contiene SQLCODE y mensajes de error.', 'El área de memoria compartida entre módulos de la aplicación 4GL.', 'C', 'Junior', 'SQLCA (incluye SQLCODE, SQLERRM) se revisa tras cada operación SQL para detectar errores.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué hace la sentencia BEGIN WORK en Informix 4GL?', 'Inicia el procesamiento de un trabajo batch de múltiples registros.', 'Marca el inicio del bloque de código principal del programa.', 'Abre una conexión nueva con el servidor de base de datos.', 'Inicia una transacción explícita en la base de datos Informix.', 'D', 'Junior', 'BEGIN WORK inicia la transacción; COMMIT WORK la confirma; ROLLBACK WORK la deshace.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué hace la sentencia COMMIT WORK en 4GL?', 'Confirma y hace permanentes todos los cambios de la transacción actual.', 'Guarda el estado del trabajo del usuario en la sesión activa.', 'Cierra la conexión con la base de datos de forma ordenada.', 'Envía los datos del formulario al servidor para su validación.', 'A', 'Junior', 'COMMIT WORK finaliza la UOW haciendo permanentes los INSERTs, UPDATEs y DELETEs.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Para qué se usa la cláusula FOREACH en Informix 4GL?', 'Itera sobre un array de variables definidas en el bloque de declaraciones.', 'Itera un SELECT automáticamente sin necesidad de OPEN/FETCH/CLOSE explícitos.', 'Itera sobre las filas de un formulario de pantalla del usuario.', 'Itera sobre los módulos cargados en la sesión actual de 4GL.', 'B', 'Junior', 'FOREACH SELECT col INTO var FROM tabla ... END FOREACH gestiona cursor internamente.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué hace INSERT en Informix 4GL?', 'Agrega un elemento a un array dinámico de 4GL.', 'Inserta texto en el área de mensajes de la pantalla de usuario.', 'Inserta un nuevo registro en la tabla de la base de datos Informix.', 'Inserta un módulo 4GL en el flujo de ejecución del programa.', 'C', 'Junior', 'INSERT INTO tabla (cols) VALUES (vars) es igual que SQL estándar pero con variables 4GL.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué es un módulo GLOBALS en 4GL?', 'Una librería de funciones de manejo de pantallas de usuario.', 'Un módulo predefinido que contiene las funciones estándar del sistema.', 'La sección del programa donde se definen constantes de configuración.', 'Un archivo .4gl que define variables compartidas entre múltiples programas.', 'D', 'Junior', 'GLOBALS \"archivo.4gl\" permite compartir variables de tipo GLOBALS entre módulos distintos.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cómo se llama a una función en Informix 4GL?', 'CALL nombre_funcion(params) o LET var = nombre_funcion(params).', 'EXECUTE nombre_funcion WITH params RETURNING vars.', 'INVOKE nombre_funcion USING params INTO result.', 'RUN nombre_funcion(params) RETURNING result.', 'A', 'Junior', 'CALL para funciones sin retorno; LET var = funcion() para funciones con valor de retorno.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué hace DISPLAY en Informix 4GL?', 'Muestra un reporte de datos en la impresora predeterminada del sistema.', 'Muestra un valor o mensaje en la pantalla del terminal del usuario.', 'Define los atributos visuales del formulario de pantalla activo.', 'Visualiza el contenido de la tabla en formato tabular en pantalla.', 'B', 'Junior', 'DISPLAY texto AT row, col muestra en pantalla; DISPLAY variable muestra su contenido.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Para qué sirve OPEN FORM en Informix 4GL?', 'Inicia la conexión entre el formulario y la tabla de la base de datos.', 'Abre el editor de formularios para modificar la pantalla en ejecución.', 'Carga en memoria el formulario compilado .frm para su uso por el programa.', 'Muestra el formulario en pantalla e inicia el modo de entrada de datos.', 'C', 'Junior', 'OPEN FORM form_name FROM \"archivo.frm\"; luego DISPLAY FORM form_name lo muestra.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué hace INPUT en Informix 4GL?', 'Recibe parámetros externos pasados al programa al momento de iniciarlo.', 'Lee datos de un archivo de texto de entrada para procesamiento batch.', 'Captura la entrada del teclado como caracteres individuales del usuario.', 'Permite al usuario ingresar datos en los campos de un formulario de pantalla.', 'D', 'Junior', 'INPUT BY NAME var1, var2 asocia variables con campos del formulario para captura de datos.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cómo se define el tipo DATE en Informix 4GL?', 'DEFINE fecha DATE; almacena fechas en formato nativo de Informix.', 'DEFINE fecha CHAR(10); las fechas se guardan como cadena \"YYYY-MM-DD\".', 'DEFINE fecha INTEGER; las fechas se guardan como días desde 01/01/1900.', 'DEFINE fecha DATETIME YEAR TO DAY para compatibilidad con SQL estándar.', 'A', 'Junior', 'DATE en 4GL es tipo nativo; se formatea con MDY(month,day,year) y TODAY retorna la actual.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué hace la función TODAY en Informix 4GL?', 'Retorna la fecha y hora actual como tipo DATETIME.', 'Retorna la fecha actual del sistema como tipo DATE.', 'Retorna el número de días transcurridos desde el inicio del año.', 'Retorna la fecha actual formateada como texto en formato YYYY-MM-DD.', 'B', 'Junior', 'LET fecha = TODAY retorna DATE actual; CURRENT retorna DATETIME con hora.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cómo se define un array en Informix 4GL?', 'DIM arr(100) AS tipo_dato.', 'DEFINE arr tipo_dato[100].', 'DEFINE arr ARRAY[100] OF tipo_dato.', 'CREATE ARRAY arr OF tipo_dato SIZE 100.', 'C', 'Junior', 'ARRAY[n] define array estático; la indexación en 4GL empieza desde 1, no desde 0.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué hace ROLLBACK WORK en Informix 4GL?', 'Cancela el formulario activo y regresa al menú principal.', 'Regresa el cursor a la primera fila del resultado del SELECT.', 'Reinicia la aplicación desde el punto de inicio de sesión del usuario.', 'Deshace todos los cambios de la transacción actual sin aplicarlos.', 'D', 'Junior', 'ROLLBACK WORK revierte INSERT/UPDATE/DELETE desde el último BEGIN WORK o COMMIT WORK.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué es NOTFOUND en Informix 4GL?', 'Una constante que equivale a 100 indicando que no se encontró ninguna fila.', 'Un tipo de error que indica que la tabla buscada no existe en la BD.', 'Una función que verifica si un registro existe antes de leerlo.', 'Un código de retorno de función que indica operación sin resultado.', 'A', 'Junior', 'IF STATUS = NOTFOUND es el idiom 4GL para verificar que un SELECT no devolvió filas.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Para qué sirve el comando c4gl?', 'Conecta la aplicación 4GL al servidor de base de datos Informix.', 'Compila archivos fuente .4gl a código objeto o ejecutable.', 'Genera código fuente 4GL a partir de un esquema de base de datos.', 'Convierte programas ESQL/C a equivalentes en Informix 4GL.', 'B', 'Junior', 'c4gl -o ejecutable fuente.4gl compila el programa; con múltiples archivos los enlaza.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué diferencia hay entre CHAR y VARCHAR en Informix?', 'CHAR es más eficiente para búsquedas; VARCHAR para inserciones masivas.', 'VARCHAR solo acepta caracteres numéricos; CHAR acepta cualquier carácter.', 'CHAR tiene longitud fija rellena con espacios; VARCHAR ajusta al tamaño real.', 'No hay diferencia; son alias del mismo tipo en versiones recientes.', 'C', 'Junior', 'CHAR(n) siempre ocupa n bytes; VARCHAR(n) ocupa solo lo necesario hasta n bytes.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué hace la sentencia UPDATE en Informix 4GL?', 'Actualiza el índice de la tabla para optimizar las consultas posteriores.', 'Actualiza la definición de la tabla en el catálogo del sistema.', 'Refresca la pantalla del formulario con los datos más recientes de la BD.', 'Modifica los valores de columnas en filas existentes de una tabla.', 'D', 'Junior', 'UPDATE tabla SET col=val WHERE condicion es igual que SQL estándar en Informix 4GL.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué hace UPDATE WHERE CURRENT OF cursor en Informix 4GL?', 'Actualiza la fila actual apuntada por el cursor abierto con FOR UPDATE.', 'Actualiza todas las filas que coincidan con la posición actual del cursor.', 'Mueve el cursor a la siguiente fila y actualiza la anterior automáticamente.', 'Actualiza el cursor con la consulta SQL modificada en tiempo de ejecución.', 'A', 'Semi-Senior', 'WHERE CURRENT OF es la forma eficiente de actualizar la fila exacta que FETCH recuperó.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué hace la función CLIPPED en Informix 4GL?', 'Recorta una cadena al número de caracteres especificado.', 'Elimina los espacios en blanco del final de una cadena CHAR.', 'Reemplaza los espacios en blanco dentro de la cadena por underscores.', 'Convierte la cadena a mayúsculas eliminando caracteres especiales.', 'B', 'Semi-Senior', 'nombre CLIPPED retorna la cadena sin trailing spaces; esencial al concatenar campos CHAR.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué hace el operador || en Informix 4GL?', 'Define el separador de campos en el archivo de importación de datos.', 'Es el operador OR lógico para condiciones en sentencias IF.', 'Concatena dos cadenas de texto: \"Hola\" || \" \" || \"mundo\".', 'Declara un tipo de datos de cadena de longitud variable en la definición.', 'C', 'Semi-Senior', '|| es el operador de concatenación de cadenas tanto en SQL de Informix como en 4GL.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cómo se pasan parámetros a un cursor dinámico en Informix 4GL?', 'SET PARAM var FOR c; luego OPEN c aplica los parámetros automáticamente.', 'OPEN c WITH PARAMETERS (var1, var2) reemplaza los ? en el SELECT.', 'DEFINE PARAM c CURSOR FOR SELECT ... WHERE col = :var.', 'DECLARE c CURSOR FOR SELECT ... WHERE col = ?; OPEN c USING var.', 'D', 'Semi-Senior', 'El ? es el marcador de posición; OPEN cursor USING variable1, variable2 los sustituye.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cómo se implementa un menú en Informix 4GL?', 'Con el bloque MENU \"titulo\" COMMAND \"opcion\" ... END MENU.', 'Con DISPLAY MENU FROM array de opciones al inicio del programa.', 'Con un formulario .per que contiene botones de menú en los campos.', 'Con la sentencia SHOW MENU nombre_menu RETURNING opcion_elegida.', 'A', 'Semi-Senior', 'MENU...COMMAND \"Agregar\"... COMMAND \"Salir\"... END MENU crea el menú de texto estándar.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué hace CONSTRUCT en Informix 4GL?', 'Construye un nuevo objeto de base de datos a partir de una plantilla.', 'Permite al usuario construir dinámicamente la cláusula WHERE de un SELECT.', 'Inicializa y construye el formulario de pantalla cargando los datos iniciales.', 'Crea el SQL dinámico en una variable de cadena para su ejecución posterior.', 'B', 'Semi-Senior', 'CONSTRUCT BY NAME clausula_where ON tabla.* permite búsquedas flexibles sin SQL manual.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cómo se ejecuta SQL dinámico en Informix 4GL?', 'DYNAMIC QUERY sql INTO vars ejecuta el SQL almacenado en la variable.', 'EXECUTE IMMEDIATE \"SELECT...\" INTO vars; es la forma directa.', 'LET sql = \"SELECT ...\"; PREPARE stm FROM sql; EXECUTE stm [USING vars].', 'RUN SQL sql USING vars INTO vars es la instrucción de SQL dinámico.', 'C', 'Semi-Senior', 'PREPARE compila el SQL dinámico; EXECUTE lo corre; DECLARE cursor FOR stm para SELECTs.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cómo se define un registro (RECORD) en Informix 4GL?', 'DEFINE reg LIKE tabla.* para replicar la estructura de una tabla.', 'DEFINE reg STRUCTURE {col1 CHAR(10), col2 INTEGER}.', 'CREATE RECORD reg (col1 CHAR(10), col2 INTEGER).', 'DEFINE reg RECORD col1 CHAR(10), col2 INTEGER END RECORD.', 'D', 'Semi-Senior', 'RECORD agrupa campos relacionados; DEFINE reg LIKE tabla.* copia el esquema de una tabla.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué hace DISPLAY ARRAY en Informix 4GL?', 'Muestra un array de registros en un scroll de pantalla navegable.', 'Imprime los elementos del array en la consola de texto del sistema.', 'Visualiza el contenido del array en formato de tabla en pantalla fija.', 'Envía el array al reporte de salida del módulo REPORT del programa.', 'A', 'Semi-Senior', 'DISPLAY ARRAY muestra un subarray del array en un campo de scroll del formulario .per.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué hace la función MDY() en Informix 4GL?', 'Formatea una fecha en el orden Mes-Día-Año para su impresión.', 'Crea un valor DATE a partir de componentes numéricos mes, día, año.', 'Extrae los componentes mes, día y año de una fecha almacenada.', 'Convierte una cadena de texto en formato \"MM/DD/YYYY\" a tipo DATE.', 'B', 'Semi-Senior', 'LET fecha = MDY(12, 31, 2024) crea una DATE; DATE() convierte un string a DATE.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué hace PAUSE en Informix 4GL?', 'Congela la pantalla actual mientras se procesa una consulta en background.', 'Suspende el proceso actual por un número de segundos especificado.', 'Pausa la ejecución mostrando un mensaje hasta que el usuario presione una tecla.', 'Hace una pausa entre transacciones para evitar saturar el servidor.', 'C', 'Semi-Senior', 'PAUSE muestra \"Press any key to continue.\" y espera; útil antes de regresar al menú.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué hace SET EXPLAIN ON en Informix?', 'Muestra estadísticas de uso de índices en tiempo real en pantalla.', 'Activa el modo de trazado SQL mostrando cada sentencia en el log.', 'Explica las opciones disponibles del onconfig al administrador.', 'Genera un archivo explain.out con el plan de acceso de cada SQL ejecutado.', 'D', 'Senior', 'El plan en explain.out muestra si se usa índice, nested loops, hash join o full scan.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué es ONCONFIG en Informix y cuál es su función?', 'El archivo de configuración principal del servidor Informix Dynamic Server.', 'La herramienta de administración gráfica para configurar el servidor.', 'El programa que valida la configuración de la instancia Informix.', 'El registro del sistema operativo donde Informix guarda su configuración.', 'A', 'Senior', 'onconfig contiene parámetros como DBSPACETEMP, BUFFERPOOL, LOCKS y MAX CONNECTIONS.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cuándo se usa UPDATE STATISTICS en Informix?', 'Para actualizar los índices de la tabla cuando hay fragmentación excesiva.', 'Para actualizar las estadísticas de las tablas que el optimizador usa en los planes.', 'Para actualizar el catálogo del sistema con los últimos cambios del esquema.', 'Para forzar la reconstrucción del árbol B de los índices de la tabla.', 'B', 'Senior', 'UPDATE STATISTICS FOR TABLE tabla activa el optimizador de consultas con datos reales.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué es la fragmentación (partitioning) en Informix y para qué sirve?', 'Particionar el log de transacciones en segmentos para mayor rendimiento.', 'Dividir el código fuente de la aplicación en múltiples módulos .4gl.', 'Distribuir filas de una tabla en múltiples dbspaces según una expresión.', 'Separar los índices de los datos en dbspaces diferentes para rendimiento.', 'C', 'Senior', 'FRAGMENT BY RANGE o EXPRESSION distribuye datos; mejora parallelismo y mantenimiento.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cómo se implementa una transacción distribuida en Informix 4GL?', 'Con triggers en cada servidor que replican automáticamente los cambios.', 'Con BEGIN DISTRIBUTED WORK ... COMMIT ALL que sincroniza múltiples BDs.', 'Con REMOTE BEGIN WORK en cada servidor y GLOBAL COMMIT al finalizar.', 'Con conexiones múltiples y el uso de XA (Extended Architecture) con 2PC.', 'D', 'Senior', 'XA protocol con Two-Phase Commit permite ACID en transacciones entre múltiples instancias.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cómo se hace backup online en Informix usando ontape?', 'ontape -s para backup nivel 0 (completo) mientras la BD está en línea.', 'ontape -b DATABASE nombre hace backup solo de la base especificada.', 'ontape -o archive genera el backup sin interrumpir las transacciones.', 'ontape -full hace backup completo requiriendo poner la instancia en modo quiesce.', 'A', 'Senior', 'ontape -s -L 0 hace backup nivel 0 (full); -L 1 nivel 1 (incremental desde nivel 0).', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Cómo se monitorean los bloqueos activos (locks) en Informix?', 'Con oncheck -cl que verifica la consistencia de los locks de la instancia.', 'Con onstat -k que muestra todos los locks activos y las sesiones que los mantienen.', 'Con SELECT * FROM syslocks en la base de datos sysmaster del servidor.', 'Con onstat -g ses que lista las sesiones con bloqueos activos pendientes.', 'B', 'Senior', 'onstat -k muestra el tipo de lock (S, X, IS, IX), la tabla/fila y la sesión propietaria.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Para qué sirve oncheck en Informix y cuándo se usa?', 'Para verificar las conexiones activas y el uso de recursos de memoria.', 'Para comprobar la configuración del onconfig antes de arrancar el servidor.', 'Para verificar la consistencia e integridad de los datos y las páginas de disco.', 'Para comprobar si los backups de ontape son válidos y restaurables.', 'C', 'Senior', 'oncheck -cd (datos) y -ci (índices) detectan corrupción de páginas en los dbspaces.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué es un dbspace en Informix y cómo se crea?', 'Un espacio de base de datos temporal usado para ordenamiento de joins.', 'Un directorio del sistema de archivos donde Informix guarda sus tablas.', 'Un área de memoria compartida para el buffer pool de la instancia.', 'Un espacio de almacenamiento lógico mapeado a chunks de disco; se crea con onspaces -c.', 'D', 'Senior', 'onspaces -c -d nombre -p path_chunk -o offset -s size crea dbspace con su primer chunk.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('informix', '¿Qué instrucción actualiza registros en Informix 1?', 'UPDATE', 'SET', 'MODIFY', 'CHANGE', 'A', 'Junior', 'UPDATE se usa para modificar datos existentes.', 1);
