INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué es la computación en la nube (Cloud Computing)?', 'La entrega de servicios de cómputo (servidores, storage, DB) por internet.', 'Un tipo de hardware instalado en oficinas para procesar datos localmente.', 'Un protocolo de comunicación para transferir datos entre dispositivos.', 'Una red privada que conecta múltiples centros de datos corporativos.', 'A', 'Junior', 'Cloud Computing ofrece recursos bajo demanda (IaaS, PaaS, SaaS) con pago por uso.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué es Kubernetes en el contexto de aplicaciones IA en la nube?', 'Un framework de ML para entrenar modelos en múltiples GPUs en paralelo.', 'Un orquestador de contenedores para desplegar y escalar aplicaciones.', 'Una plataforma de monitoreo de modelos de IA en tiempo real.', 'Un sistema de bases de datos distribuidas para almacenar embeddings.', 'B', 'Junior', 'Kubernetes gestiona pods de contenedores, auto-scaling y load balancing para APIs de IA.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué es el alucinamiento (hallucination) en LLMs?', 'Cuando el modelo rechaza responder por restricciones de seguridad.', 'Cuando el modelo genera respuestas repetidas sin variación creativa.', 'Cuando el modelo genera información falsa o inventada como si fuera verdadera.', 'Cuando el modelo olvida el contexto previo de la conversación actual.', 'C', 'Junior', 'Las alucinaciones ocurren porque los LLMs predicen tokens plausibles, no verifican hechos.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué hace la técnica Few-Shot Prompting?', 'Selecciona pocos tokens relevantes del contexto para responder.', 'Entrena el modelo con pocos ejemplos de forma rápida y eficiente.', 'Reduce la cantidad de tokens del prompt para ahorrar costos de API.', 'Incluye algunos ejemplos de entradas y salidas en el prompt para guiar al modelo.', 'D', 'Junior', 'Few-shot: prompt=\"Traducir inglés→español. apple→manzana. car→coche. house→?\"', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué es MLflow en el contexto de MLOps?', 'Una plataforma open-source para rastrear experimentos y versionar modelos ML.', 'Un framework de ML de Google para entrenar redes neuronales en la nube.', 'Un orquestador de pipelines de datos para preparar datasets de entrenamiento.', 'Una herramienta de visualización de métricas de modelos en producción.', 'A', 'Junior', 'MLflow registra parámetros, métricas y artefactos por experimento para reproducibilidad.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué es el Chain-of-Thought (CoT) prompting?', 'Encadenar múltiples LLMs donde la salida de uno es la entrada del siguiente.', 'Técnica que pide al modelo razonar paso a paso antes de dar la respuesta.', 'Una cadena de prompts almacenados en base de datos para reutilización.', 'Técnica para reducir tokens concatenando prompts relacionados entre sí.', 'B', 'Semi-Senior', '\"Piensa paso a paso\" mejora la precisión en tareas de razonamiento matemático y lógico.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué es el Model Context Protocol (MCP) de Anthropic?', 'Un sistema de caché para reutilizar el KV cache entre diferentes llamadas.', 'Un protocolo para gestionar el contexto de múltiples sesiones del mismo LLM.', 'Un protocolo estándar para conectar LLMs con herramientas y fuentes de datos.', 'Un protocolo de seguridad para validar los prompts antes de procesarlos.', 'C', 'Semi-Senior', 'MCP estandariza cómo los LLMs acceden a tools, recursos y prompts de sistemas externos.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué es el RLHF (Reinforcement Learning from Human Feedback)?', 'Un sistema de aprendizaje activo donde el modelo pregunta al usuario.', 'Un método para entrenar robots físicos usando retroalimentación de humanos.', 'Un proceso de validación donde humanos revisan los datasets de entrenamiento.', 'Técnica para alinear LLMs usando evaluaciones humanas como señal de recompensa.', 'D', 'Semi-Senior', 'RLHF: supervisado → reward model con preferencias humanas → RL (PPO) para alinear el LLM.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué hace el prompt system message en APIs de LLMs como OpenAI?', 'Define el rol, restricciones y comportamiento base del asistente de IA.', 'Configura los parámetros técnicos como temperatura y max tokens de la API.', 'Inicializa el historial de conversación con mensajes previos del usuario.', 'Define las funciones (tools) que el modelo puede invocar durante la sesión.', 'A', 'Semi-Senior', 'System message: \"Eres un asistente experto en COBOL que responde en español conciso.\"', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué es la perplexity y cómo se usa para evaluar LLMs?', 'El número de respuestas únicas que el modelo genera para el mismo prompt.', 'El exponente de la entropía cruzada; menor valor indica mejor modelado del lenguaje.', 'La varianza de las respuestas del modelo medida en múltiples ejecuciones.', 'El número de tokens de contexto que el modelo puede recordar correctamente.', 'B', 'Senior', 'Perplexity = e^(H); mide cuán sorprendido está el modelo ante el corpus de evaluación.', 1);
INSERT INTO `preguntas_examen` (`lenguaje`, `pregunta`, `opcion_a`, `opcion_b`, `opcion_c`, `opcion_d`, `respuesta_correcta`, `complejidad`, `explicacion`, `activo`) VALUES ('cloud_ia', '¿Qué modelo se usa en IA generativa 1?', 'RNN', 'CNN', 'LLM', 'SVM', 'C', 'Junior', 'LLM es la base de IA generativa moderna.', 1);
